window.__CONTENT_EN__=window.__CONTENT_EN__||{};window.__CONTENT_EN__[24]={"2400":{"example:2400:exzh":"I have two sisters.","example:2400:exzh2":"She is my sister.","example:2400:exzh3":"I want to go on a trip with my sisters.","example:2400:exzh4":"My sisters get along very well.","example:2400:exzh5":"It's fun to have sisters."},"2401":{"example:2401:exzh":"Tomorrow is my day off, so I'll relax at home.","example:2401:exzh2":"On my days off, I often go see movies with friends.","example:2401:exzh3":"Please turn off your phone before going to bed.","example:2401:exzh4":"When I went out, I forgot to turn off the air conditioner.","example:2401:exzh5":"Please turn off your microphone during the meeting."},"2403":{"example:2403:exzh":"This painting needs restoration.","example:2403:exzh2":"He is restoring an old building.","example:2403:exzh3":"The restoration work will take a year.","example:2403:exzh4":"I tried restoring furniture myself.","example:2403:exzh5":"It's safest to hire a restoration professional."},"2404":{"example:2404:exzh":"This month's salary is a little low.","example:2404:exzh2":"I'm waiting for my salary to be deposited.","example:2404:exzh3":"He works at a company with a high salary.","example:2404:exzh4":"Please check your payslip.","example:2404:exzh5":"I'd be happy if my salary went up."},"2405":{"example:2405:exzh":"Her favorite color is pink.","example:2405:exzh2":"I decorated the room in pink.","example:2405:exzh3":"Pink flowers are blooming.","example:2405:exzh4":"He is wearing a pink shirt.","example:2405:exzh5":"I want a pink skirt.","grammar:2405:ex:trans":"Her favorite color is pink.","grammar:2405:ex:structure":"好きな色はピンクです","grammar:2405:ex:explain":"The point here is the attributive use of a na-adjective. When 「好き」 (to like) modifies the following noun 「色」, it has to take 「な」 to become 「好きな色」; this 「な」 is the attributive form of a na-adjective, and it can't be dropped or attached directly the way an i-adjective can. The topic 「好きな色」 is marked with 「は」, and the sentence ends with the judgment 「ピンクです」, so the whole thing means \"the color she likes is pink.\"","grammar:2405:ex:words:0:zh":"she","grammar:2405:ex:words:0:note":"かのじょ","grammar:2405:ex:words:0:pos":"pronoun","grammar:2405:ex:words:1:zh":"'s","grammar:2405:ex:words:1:pos":"particle","grammar:2405:ex:words:2:zh":"to like","grammar:2405:ex:words:2:note":"すき","grammar:2405:ex:words:2:pos":"na-adjective","grammar:2405:ex:words:3:zh":"(attributive form)","grammar:2405:ex:words:3:pos":"auxiliary verb","grammar:2405:ex:words:4:zh":"color","grammar:2405:ex:words:4:note":"いろ","grammar:2405:ex:words:4:pos":"noun","grammar:2405:ex:words:5:zh":"(topic)","grammar:2405:ex:words:5:pos":"particle","grammar:2405:ex:words:6:zh":"Pink","grammar:2405:ex:words:6:note":"loanword","grammar:2405:ex:words:6:pos":"noun","grammar:2405:ex:words:7:zh":"is","grammar:2405:ex:words:7:pos":"copula","grammar:2405:ex:points:0":"❗ピンク: pink.","grammar:2405:ex:points:1":"ピンク: pink.","grammar:2405:ex2:trans":"I decorated the room in pink.","grammar:2405:ex2:structure":"部屋をピンクに飾りました","grammar:2405:ex2:words:0:zh":"room","grammar:2405:ex2:words:0:note":"へや","grammar:2405:ex2:words:0:pos":"noun","grammar:2405:ex2:words:1:zh":"(object marker)","grammar:2405:ex2:words:1:pos":"particle","grammar:2405:ex2:words:2:zh":"Pink","grammar:2405:ex2:words:2:note":"loanword","grammar:2405:ex2:words:2:pos":"noun","grammar:2405:ex2:words:3:zh":"(result)","grammar:2405:ex2:words:3:pos":"particle","grammar:2405:ex2:words:4:zh":"decorated","grammar:2405:ex2:words:4:note":"かざりました","grammar:2405:ex2:words:4:pos":"verb","grammar:2405:ex2:points:0":"❗〜に飾る: to decorate in…; ピンクに飾る = decorate in pink.","grammar:2405:ex2:points:1":"ピンクに飾る: decorate in pink.","grammar:2405:ex3:trans":"The pink flowers are in bloom.","grammar:2405:ex3:structure":"ピンクの花が咲いています","grammar:2405:ex3:words:0:zh":"Pink","grammar:2405:ex3:words:0:note":"loanword","grammar:2405:ex3:words:0:pos":"noun","grammar:2405:ex3:words:1:zh":"'s","grammar:2405:ex3:words:1:pos":"particle","grammar:2405:ex3:words:2:zh":"flowers","grammar:2405:ex3:words:2:note":"はな","grammar:2405:ex3:words:2:pos":"noun","grammar:2405:ex3:words:3:zh":"(nominative)","grammar:2405:ex3:words:3:pos":"particle","grammar:2405:ex3:words:4:zh":"in full bloom","grammar:2405:ex3:words:4:note":"さいています","grammar:2405:ex3:words:4:pos":"verb","grammar:2405:ex3:points:0":"❗ピンクの花: pink flowers.","grammar:2405:ex3:points:1":"ピンクの花: a pink flower.","grammar:2405:ex4:trans":"He is wearing a pink shirt.","grammar:2405:ex4:structure":"ピンクのシャツを着ています","grammar:2405:ex4:words:0:zh":"he","grammar:2405:ex4:words:0:note":"かれ","grammar:2405:ex4:words:0:pos":"pronoun","grammar:2405:ex4:words:1:zh":"(topic)","grammar:2405:ex4:words:1:pos":"particle","grammar:2405:ex4:words:2:zh":"Pink","grammar:2405:ex4:words:2:note":"loanword","grammar:2405:ex4:words:2:pos":"noun","grammar:2405:ex4:words:3:zh":"'s","grammar:2405:ex4:words:3:pos":"particle","grammar:2405:ex4:words:4:zh":"shirt","grammar:2405:ex4:words:4:note":"loanword","grammar:2405:ex4:words:4:pos":"noun","grammar:2405:ex4:words:5:zh":"(object marker)","grammar:2405:ex4:words:5:pos":"particle","grammar:2405:ex4:words:6:zh":"Wearing","grammar:2405:ex4:words:6:note":"きています","grammar:2405:ex4:words:6:pos":"verb","grammar:2405:ex4:points:0":"❗シャツ: shirt.","grammar:2405:ex4:points:1":"ピンクのシャツ: a pink shirt.","grammar:2405:ex5:trans":"I want a pink skirt.","grammar:2405:ex5:structure":"ピンクのスカートが欲しいです","grammar:2405:ex5:words:0:zh":"Pink","grammar:2405:ex5:words:0:note":"loanword","grammar:2405:ex5:words:0:pos":"noun","grammar:2405:ex5:words:1:zh":"'s","grammar:2405:ex5:words:1:pos":"particle","grammar:2405:ex5:words:2:zh":"skirt","grammar:2405:ex5:words:2:note":"loanword","grammar:2405:ex5:words:2:pos":"noun","grammar:2405:ex5:words:3:zh":"(object)","grammar:2405:ex5:words:3:pos":"particle","grammar:2405:ex5:words:4:zh":"to want to","grammar:2405:ex5:words:4:note":"ほしい","grammar:2405:ex5:words:4:pos":"adjective","grammar:2405:ex5:words:5:zh":"(polite form)","grammar:2405:ex5:words:5:pos":"copula","grammar:2405:ex5:points:0":"❗スカート: skirt; 〜が欲しい = to want…","grammar:2405:ex5:points:1":"ピンクのスカート: a pink skirt."},"2406":{"example:2406:exzh":"He works at a new company.","example:2406:exzh2":"Working hours are from 9 to 5.","example:2406:exzh3":"Please refrain from private conversations during work hours.","example:2406:exzh4":"I'll go out once work is over.","example:2406:exzh5":"She works in the city center."},"2408":{"example:2408:exzh":"He is openly gay.","example:2408:exzh2":"The gay community is involved in various activities.","example:2408:exzh3":"I'm thinking about gay rights.","example:2408:exzh4":"She has many gay friends.","example:2408:exzh5":"I want to join a gay parade."},"2410":{"example:2410:exzh":"The children are playing in the garden.","example:2410:exzh2":"This park is a beautiful garden.","example:2410:exzh3":"There are many flowers in the garden.","example:2410:exzh4":"He helps manage the garden.","example:2410:exzh5":"I like growing flowers in this garden."},"2411":{"example:2411:exzh":"Please write the katakana 「ロ」 using the Roman alphabet.","example:2411:exzh2":"He isn't good at pronouncing 「ロ」.","example:2411:exzh3":"The katakana 「ロ」 looks like a square.","example:2411:exzh4":"Let's make example sentences using the character 「ロ」.","example:2411:exzh5":"Writing the character 「ロ」 is easy."},"2412":{"example:2412:exzh":"Please include all expenses.","example:2412:exzh2":"His opinion should be included too.","example:2412:exzh3":"Tax is included in this price.","example:2412:exzh4":"Including the participants, there are 30 people at the meeting.","example:2412:exzh5":"If you include her explanation too, it's easier to understand."},"2413":{"example:2413:exzh":"Historically, there have been many cases of massacre.","example:2413:exzh2":"Massacre should never be allowed.","example:2413:exzh3":"The film depicts a massacre during the war.","example:2413:exzh4":"A protest against the massacre was held.","example:2413:exzh5":"That country has a history of experiencing massacre."},"2415":{"example:2415:exzh":"He testified at the prosecution's request.","example:2415:exzh2":"The prosecution is proceeding with its investigation of the case.","example:2415:exzh3":"The prosecution's judgment will affect the outcome of the case.","example:2415:exzh4":"She works as a staff member at the public prosecutors' office.","example:2415:exzh5":"I ended up being questioned by the prosecution."},"2417":{"example:2417:exzh":"He is a lieutenant colonel in the air force.","example:2417:exzh2":"I'm aiming to be promoted to lieutenant colonel.","example:2417:exzh3":"A lieutenant colonel is a unit commander.","example:2417:exzh4":"She shows respect for the lieutenant colonel.","example:2417:exzh5":"He is fulfilling his duties as a lieutenant colonel."},"2418":{"example:2418:exzh":"He jumped high.","example:2418:exzh2":"I jumped over the puddle to the other side.","example:2418:exzh3":"The children were so happy that they jumped again and again.","example:2418:exzh4":"It's impossible to jump over that fence.","example:2418:exzh5":"He jumped six meters in the long jump."},"2419":{"example:2419:exzh":"He enlisted in the navy as a marine.","example:2419:exzh2":"Training for marines is extremely tough.","example:2419:exzh3":"She carried out her duties as a marine.","example:2419:exzh4":"Marines were also dispatched for disaster relief.","example:2419:exzh5":"A young marine was honored at the ceremony."},"2420":{"example:2420:exzh":"After being held captive, he regained his freedom.","example:2420:exzh2":"Confinement is a violation of human rights.","example:2420:exzh3":"The criminal who was held in confinement will go on trial.","example:2420:exzh4":"The case began with a confinement.","example:2420:exzh5":"Being confined for a long time is mentally exhausting."},"2421":{"example:2421:exzh":"This diagnostic method is common.","example:2421:exzh2":"Early diagnosis is important.","example:2421:exzh3":"She went to the hospital to get a diagnosis.","example:2421:exzh4":"I'm waiting for the results of the diagnosis.","example:2421:exzh5":"The doctor made the correct diagnosis."},"2422":{"example:2422:exzh":"I'm cooking in the kitchen.","example:2422:exzh2":"The new kitchen is done.","example:2422:exzh3":"There's a big refrigerator in the kitchen.","example:2422:exzh4":"He cleaned the kitchen.","example:2422:exzh5":"The cupboard in the kitchen is tall.","grammar:2422:ex:trans":"I'm cooking in the kitchen.","grammar:2422:ex:structure":"キッチンで料理を作っています","grammar:2422:ex:explain":"This sentence combines the location particle 「で」 with the progressive 「〜ている」. In 「キッチンで」, 「で」 marks where the action takes place, 'in the kitchen'; the object 「料理」 takes 「を」, and the te-form of 「作る」 (to make), 「作って」, plus 「います」 gives 「作っています」, the ongoing state 'is making'. The sentence describes the speaker cooking in the kitchen right now — a typical sentence for an action in progress.","grammar:2422:ex:words:0:zh":"kitchen","grammar:2422:ex:words:0:note":"loanword","grammar:2422:ex:words:0:pos":"noun","grammar:2422:ex:words:1:zh":"(place)","grammar:2422:ex:words:1:pos":"particle","grammar:2422:ex:words:2:zh":"meal","grammar:2422:ex:words:2:note":"りょうり","grammar:2422:ex:words:2:pos":"noun","grammar:2422:ex:words:3:zh":"(object marker)","grammar:2422:ex:words:3:pos":"particle","grammar:2422:ex:words:4:zh":"is doing","grammar:2422:ex:words:4:note":"つくっています","grammar:2422:ex:words:4:pos":"verb","grammar:2422:ex:points:1":"キッチン: kitchen.","grammar:2422:ex2:trans":"The new kitchen is finished.","grammar:2422:ex2:structure":"新しいキッチンができました","grammar:2422:ex2:words:0:zh":"new","grammar:2422:ex2:words:0:note":"あたらしい","grammar:2422:ex2:words:0:pos":"adjective","grammar:2422:ex2:words:1:zh":"kitchen","grammar:2422:ex2:words:1:note":"loanword","grammar:2422:ex2:words:1:pos":"noun","grammar:2422:ex2:words:2:zh":"(nominative)","grammar:2422:ex2:words:2:pos":"particle","grammar:2422:ex2:words:3:zh":"done","grammar:2422:ex2:words:3:pos":"verb","grammar:2422:ex2:points:0":"❗できる: to be completed, to be finished (intransitive verb).","grammar:2422:ex2:points:1":"できる: to be completed.","grammar:2422:ex3:trans":"There is a big refrigerator in the kitchen.","grammar:2422:ex3:structure":"キッチンには大きな冷蔵庫があります","grammar:2422:ex3:words:0:zh":"kitchen","grammar:2422:ex3:words:0:note":"loanword","grammar:2422:ex3:words:0:pos":"noun","grammar:2422:ex3:words:1:zh":"(location of existence)","grammar:2422:ex3:words:1:pos":"particle","grammar:2422:ex3:words:2:zh":"(contrast)","grammar:2422:ex3:words:2:pos":"particle","grammar:2422:ex3:words:3:zh":"big","grammar:2422:ex3:words:3:note":"おおきな","grammar:2422:ex3:words:3:pos":"pre-noun adjectival","grammar:2422:ex3:words:4:zh":"refrigerator","grammar:2422:ex3:words:4:note":"れいぞうこ","grammar:2422:ex3:words:4:pos":"noun","grammar:2422:ex3:words:5:zh":"(nominative)","grammar:2422:ex3:words:5:pos":"particle","grammar:2422:ex3:words:6:zh":"there is / are","grammar:2422:ex3:words:6:pos":"verb","grammar:2422:ex3:points:0":"❗冷蔵庫: refrigerator (冷蔵 + 庫).","grammar:2422:ex3:points:1":"冷蔵庫: refrigerator.","grammar:2422:ex4:trans":"He cleaned the kitchen.","grammar:2422:ex4:structure":"彼はキッチンを掃除しました","grammar:2422:ex4:words:0:zh":"he","grammar:2422:ex4:words:0:note":"かれ","grammar:2422:ex4:words:0:pos":"pronoun","grammar:2422:ex4:words:1:zh":"(topic)","grammar:2422:ex4:words:1:pos":"particle","grammar:2422:ex4:words:2:zh":"kitchen","grammar:2422:ex4:words:2:note":"loanword","grammar:2422:ex4:words:2:pos":"noun","grammar:2422:ex4:words:3:zh":"(object marker)","grammar:2422:ex4:words:3:pos":"particle","grammar:2422:ex4:words:4:zh":"cleaned","grammar:2422:ex4:words:4:note":"そうじしました","grammar:2422:ex4:words:4:pos":"verb","grammar:2422:ex4:points:0":"❗キッチンを掃除する: to clean the kitchen.","grammar:2422:ex4:points:1":"掃除する: to clean.","grammar:2422:ex5:trans":"The kitchen cupboard is high.","grammar:2422:ex5:structure":"キッチンの戸棚は高いです","grammar:2422:ex5:words:0:zh":"kitchen","grammar:2422:ex5:words:0:note":"loanword","grammar:2422:ex5:words:0:pos":"noun","grammar:2422:ex5:words:1:zh":"'s","grammar:2422:ex5:words:1:pos":"particle","grammar:2422:ex5:words:2:zh":"cupboard","grammar:2422:ex5:words:2:note":"とだな","grammar:2422:ex5:words:2:pos":"noun","grammar:2422:ex5:words:3:zh":"(topic)","grammar:2422:ex5:words:3:pos":"particle","grammar:2422:ex5:words:4:zh":"tall","grammar:2422:ex5:words:4:note":"たかい","grammar:2422:ex5:words:4:pos":"adjective","grammar:2422:ex5:words:5:zh":"(polite form)","grammar:2422:ex5:words:5:pos":"copula","grammar:2422:ex5:points:0":"❗戸棚: cupboard, kitchen cabinet (戸 + 棚).","grammar:2422:ex5:points:1":"戸棚: cupboard."},"2423":{"example:2423:exzh":"The sky stretches out wide.","example:2423:exzh2":"The fire quickly spread to the house next door.","example:2423:exzh3":"The new project is expanding.","example:2423:exzh4":"The view of the flowers spreading out is beautiful.","example:2423:exzh5":"Information spreads fast."},"2424":{"example:2424:exzh":"I was ordered to fire on the enemy.","example:2424:exzh2":"He practiced shooting at a target.","example:2424:exzh3":"I'm confident I can hit the target.","example:2424:exzh4":"This gun is easy to fire.","example:2424:exzh5":"The timing of the shot is very important."},"2425":{"example:2425:exzh":"I visited a friend's house.","example:2425:exzh2":"He traveled to visit his relatives.","example:2425:exzh3":"I'm planning to visit my grandmother tomorrow.","example:2425:exzh4":"Tourists are visiting historical sites.","example:2425:exzh5":"I'm planning to visit a school to make new friends."},"2426":{"example:2426:exzh":"She really is a beauty.","example:2426:exzh2":"I live in a city full of beautiful women.","example:2426:exzh3":"Beautiful women always draw everyone's attention.","example:2426:exzh4":"He was staring at that beautiful woman.","example:2426:exzh5":"Beautiful women always have a special charm.","grammar:2426:ex:trans":"She really is a beauty.","grammar:2426:ex:structure":"彼女は本当に美人です","grammar:2426:ex:explain":"This sentence has a noun predicate modified by an adverb. The topic 「彼女」 takes 「は」, and the predicate 「美人」 (a beautiful woman) is a noun, with 「です」 making the judgment. The adverb in front, 「本当に」 (really, truly), strengthens the tone and modifies the whole 'is a beauty' statement. Note that 「本当に」 is formed from the noun 「本当」 plus 「に」 to make an adverb. The sentence emphasizes 'she really is a beauty'.","grammar:2426:ex:words:0:zh":"she","grammar:2426:ex:words:0:note":"かのじょ","grammar:2426:ex:words:0:pos":"pronoun","grammar:2426:ex:words:1:zh":"(topic)","grammar:2426:ex:words:1:pos":"particle","grammar:2426:ex:words:2:zh":"really","grammar:2426:ex:words:2:note":"ほんとうに","grammar:2426:ex:words:2:pos":"adverb","grammar:2426:ex:words:3:zh":"a beautiful woman","grammar:2426:ex:words:3:note":"びじん","grammar:2426:ex:words:3:pos":"noun","grammar:2426:ex:words:4:zh":"is","grammar:2426:ex:words:4:pos":"copula","grammar:2426:ex:points:0":"❗美人 (びじん): a beauty, a beautiful woman (usually referring to a woman).","grammar:2426:ex:points:1":"美人: a beauty.","grammar:2426:ex2:trans":"I live in a city with lots of beautiful women.","grammar:2426:ex2:structure":"美人が多い街に住んでいます","grammar:2426:ex2:words:0:zh":"a beautiful woman","grammar:2426:ex2:words:0:note":"びじん","grammar:2426:ex2:words:0:pos":"noun","grammar:2426:ex2:words:1:zh":"(nominative)","grammar:2426:ex2:words:1:pos":"particle","grammar:2426:ex2:words:2:zh":"many","grammar:2426:ex2:words:2:note":"おおい","grammar:2426:ex2:words:2:pos":"adjective","grammar:2426:ex2:words:3:zh":"city","grammar:2426:ex2:words:3:note":"まち","grammar:2426:ex2:words:3:pos":"noun","grammar:2426:ex2:words:4:zh":"(location of existence)","grammar:2426:ex2:words:4:pos":"particle","grammar:2426:ex2:words:5:zh":"live (there)","grammar:2426:ex2:words:5:note":"すんでいます","grammar:2426:ex2:words:5:pos":"verb","grammar:2426:ex2:points:0":"❗美人が多い街: a town full of beautiful women.","grammar:2426:ex2:points:1":"美人が多い: there are many beautiful women.","grammar:2426:ex3:trans":"Beautiful women always attract attention.","grammar:2426:ex3:structure":"美人はいつも注目を集めます","grammar:2426:ex3:words:0:zh":"a beautiful woman","grammar:2426:ex3:words:0:note":"びじん","grammar:2426:ex3:words:0:pos":"noun","grammar:2426:ex3:words:1:zh":"(topic)","grammar:2426:ex3:words:1:pos":"particle","grammar:2426:ex3:words:2:zh":"always","grammar:2426:ex3:words:2:pos":"adverb","grammar:2426:ex3:words:3:zh":"attention","grammar:2426:ex3:words:3:note":"ちゅうもく","grammar:2426:ex3:words:3:pos":"noun","grammar:2426:ex3:words:4:zh":"(object marker)","grammar:2426:ex3:words:4:pos":"particle","grammar:2426:ex3:words:5:zh":"attract","grammar:2426:ex3:words:5:note":"あつめます","grammar:2426:ex3:words:5:pos":"verb","grammar:2426:ex3:points:0":"❗注目を集める: to attract attention (set phrase).","grammar:2426:ex3:points:1":"注目を集める: to draw the eye.","grammar:2426:ex4:trans":"He was staring at the beautiful woman.","grammar:2426:ex4:structure":"彼は美人を見つめていました","grammar:2426:ex4:words:0:zh":"he","grammar:2426:ex4:words:0:note":"かれ","grammar:2426:ex4:words:0:pos":"pronoun","grammar:2426:ex4:words:1:zh":"(topic)","grammar:2426:ex4:words:1:pos":"particle","grammar:2426:ex4:words:2:zh":"a beautiful woman","grammar:2426:ex4:words:2:note":"びじん","grammar:2426:ex4:words:2:pos":"noun","grammar:2426:ex4:words:3:zh":"(object marker)","grammar:2426:ex4:words:3:pos":"particle","grammar:2426:ex4:words:4:zh":"was gazing at","grammar:2426:ex4:words:4:note":"みつめていました","grammar:2426:ex4:words:4:pos":"verb","grammar:2426:ex4:points:0":"❗見つめる: to gaze at, to stare at.","grammar:2426:ex4:points:1":"見つめる: to gaze.","grammar:2426:ex5:trans":"Beautiful women always have a special charm.","grammar:2426:ex5:structure":"美人には特別な魅力があります","grammar:2426:ex5:words:0:zh":"a beautiful woman","grammar:2426:ex5:words:0:note":"びじん","grammar:2426:ex5:words:0:pos":"noun","grammar:2426:ex5:words:1:zh":"(existence target — the one who has)","grammar:2426:ex5:words:1:pos":"particle","grammar:2426:ex5:words:2:zh":"(contrast)","grammar:2426:ex5:words:2:pos":"particle","grammar:2426:ex5:words:3:zh":"special","grammar:2426:ex5:words:3:note":"とくべつ","grammar:2426:ex5:words:3:pos":"na-adjective","grammar:2426:ex5:words:4:zh":"(attributive form)","grammar:2426:ex5:words:4:pos":"auxiliary verb","grammar:2426:ex5:words:5:zh":"charm","grammar:2426:ex5:words:5:note":"みりょく","grammar:2426:ex5:words:5:pos":"noun","grammar:2426:ex5:words:6:zh":"(nominative)","grammar:2426:ex5:words:6:pos":"particle","grammar:2426:ex5:words:7:zh":"there is / are","grammar:2426:ex5:words:7:pos":"verb","grammar:2426:ex5:points:0":"❗特別な魅力: a special charm.","grammar:2426:ex5:points:1":"特別な魅力: a distinctive charm."},"2427":{"example:2427:exzh":"We're considering the best method.","example:2427:exzh2":"He gave the issue careful consideration.","example:2427:exzh3":"There are many factors to consider.","example:2427:exzh4":"This project requires some consideration.","example:2427:exzh5":"She carefully considered all the options."},"2428":{"example:2428:exzh":"I'll build a new house.","example:2428:exzh2":"He's building a tall building.","example:2428:exzh3":"An old temple has been built in this village.","example:2428:exzh4":"We have plans to build a school.","example:2428:exzh5":"Building a house is hard work.","grammar:2428:ex:trans":"I'm going to build a new house.","grammar:2428:ex:structure":"〜を建てます","grammar:2428:ex:explain":"The focus is the transitive verb 「建てる」 (to build). It is a volitional transitive verb and its object takes 「を」, so 「家を建てる」 means to build a house; it must be distinguished from the intransitive 「建つ」 (for a building to go up): the former emphasizes that people build it, while the latter emphasizes that the structure rises on its own. 「建てます」 is the polite form for a future, volitional action. The whole sentence 「新しい家を建てます」 expresses the plan I'm going to build a new house.","grammar:2428:ex:words:0:zh":"new","grammar:2428:ex:words:0:note":"あたらしい","grammar:2428:ex:words:0:pos":"adjective","grammar:2428:ex:words:1:zh":"house","grammar:2428:ex:words:1:note":"いえ","grammar:2428:ex:words:1:pos":"noun","grammar:2428:ex:words:2:zh":"(object marker)","grammar:2428:ex:words:2:pos":"particle","grammar:2428:ex:words:3:zh":"to build","grammar:2428:ex:words:3:note":"たてます","grammar:2428:ex:words:3:pos":"verb","grammar:2428:ex:points:0":"❗建てる（たてる）: to build (transitive verb); vs 建つ (intransitive, to be built); 家を建てる = to build a house.","grammar:2428:ex:points:1":"家を建てる: building a house.","grammar:2428:ex2:trans":"He is building a tall building.","grammar:2428:ex2:structure":"〜を建てています","grammar:2428:ex2:words:0:zh":"he","grammar:2428:ex2:words:0:note":"かれ","grammar:2428:ex2:words:0:pos":"pronoun","grammar:2428:ex2:words:1:zh":"(topic)","grammar:2428:ex2:words:1:pos":"particle","grammar:2428:ex2:words:2:zh":"tall","grammar:2428:ex2:words:2:note":"たかい","grammar:2428:ex2:words:2:pos":"adjective","grammar:2428:ex2:words:3:zh":"building","grammar:2428:ex2:words:3:note":"loanword","grammar:2428:ex2:words:3:pos":"noun","grammar:2428:ex2:words:4:zh":"(object marker)","grammar:2428:ex2:words:4:pos":"particle","grammar:2428:ex2:words:5:zh":"is building","grammar:2428:ex2:words:5:note":"たてています","grammar:2428:ex2:words:5:pos":"verb","grammar:2428:ex2:points:0":"❗ビルを建てる: to put up a building; ビル = building.","grammar:2428:ex2:points:1":"ビルを建てる: constructing a building.","grammar:2428:ex3:trans":"Old temples stand built in this village.","grammar:2428:ex3:structure":"〜には〜が建てられています","grammar:2428:ex3:words:0:zh":"this","grammar:2428:ex3:words:0:pos":"pre-noun adjectival","grammar:2428:ex3:words:1:zh":"village","grammar:2428:ex3:words:1:note":"むら","grammar:2428:ex3:words:1:pos":"noun","grammar:2428:ex3:words:2:zh":"(location of existence)","grammar:2428:ex3:words:2:pos":"particle","grammar:2428:ex3:words:3:zh":"(contrast)","grammar:2428:ex3:words:3:pos":"particle","grammar:2428:ex3:words:4:zh":"old","grammar:2428:ex3:words:4:note":"ふるい","grammar:2428:ex3:words:4:pos":"adjective","grammar:2428:ex3:words:5:zh":"temple","grammar:2428:ex3:words:5:note":"じいん","grammar:2428:ex3:words:5:pos":"noun","grammar:2428:ex3:words:6:zh":"(nominative)","grammar:2428:ex3:words:6:pos":"particle","grammar:2428:ex3:words:7:zh":"is built","grammar:2428:ex3:words:7:note":"たてられています","grammar:2428:ex3:words:7:pos":"verb","grammar:2428:ex3:points:0":"❗建てられる: to be built (the passive form of 建てる); 寺院 = temple.","grammar:2428:ex3:points:1":"建てられている: stands built there.","grammar:2428:ex4:trans":"We have plans to build a school.","grammar:2428:ex4:structure":"〜を建てる計画があります","grammar:2428:ex4:words:0:zh":"we","grammar:2428:ex4:words:0:note":"わたしたち","grammar:2428:ex4:words:0:pos":"pronoun","grammar:2428:ex4:words:1:zh":"(topic)","grammar:2428:ex4:words:1:pos":"particle","grammar:2428:ex4:words:2:zh":"school","grammar:2428:ex4:words:2:note":"がっこう","grammar:2428:ex4:words:2:pos":"noun","grammar:2428:ex4:words:3:zh":"(object marker)","grammar:2428:ex4:words:3:pos":"particle","grammar:2428:ex4:words:4:zh":"to build","grammar:2428:ex4:words:4:note":"たてる","grammar:2428:ex4:words:4:pos":"verb","grammar:2428:ex4:words:5:zh":"plan","grammar:2428:ex4:words:5:note":"けいかく","grammar:2428:ex4:words:5:pos":"noun","grammar:2428:ex4:words:6:zh":"(nominative)","grammar:2428:ex4:words:6:pos":"particle","grammar:2428:ex4:words:7:zh":"there is / are","grammar:2428:ex4:words:7:pos":"verb","grammar:2428:ex4:points:0":"❗学校を建てる: to build a school; 〜計画がある = to have plans to …","grammar:2428:ex4:points:1":"建てる計画: a plan to build.","grammar:2428:ex5:trans":"Building a house is hard work.","grammar:2428:ex5:structure":"〜を建てるのは大変な〜です","grammar:2428:ex5:words:0:zh":"house","grammar:2428:ex5:words:0:note":"いえ","grammar:2428:ex5:words:0:pos":"noun","grammar:2428:ex5:words:1:zh":"(object marker)","grammar:2428:ex5:words:1:pos":"particle","grammar:2428:ex5:words:2:zh":"to build","grammar:2428:ex5:words:2:note":"たてる","grammar:2428:ex5:words:2:pos":"verb","grammar:2428:ex5:words:3:zh":"(nominalizer)","grammar:2428:ex5:words:3:pos":"particle","grammar:2428:ex5:words:4:zh":"(topic)","grammar:2428:ex5:words:4:pos":"particle","grammar:2428:ex5:words:5:zh":"hard","grammar:2428:ex5:words:5:note":"たいへん","grammar:2428:ex5:words:5:pos":"na-adjective","grammar:2428:ex5:words:6:zh":"(attributive form)","grammar:2428:ex5:words:6:pos":"auxiliary verb","grammar:2428:ex5:words:7:zh":"work","grammar:2428:ex5:words:7:note":"しごと","grammar:2428:ex5:words:7:pos":"noun","grammar:2428:ex5:words:8:zh":"is","grammar:2428:ex5:words:8:pos":"copula","grammar:2428:ex5:points:0":"❗〜のは大変: …ing is hard work; 大変な仕事 = a demanding job.","grammar:2428:ex5:points:1":"建てるのは大変: building a house is hard work."},"2429":{"example:2429:exzh":"Labor is an important foundation of society.","example:2429:exzh2":"His working conditions are bad.","example:2429:exzh3":"Protecting workers' rights is important.","example:2429:exzh4":"At this company, labor is strictly managed.","example:2429:exzh5":"Labor builds the foundation of daily life."},"2430":{"example:2430:exzh":"He was executed as a criminal.","example:2430:exzh2":"The laws on execution are very strict.","example:2430:exzh3":"Methods of execution differ from country to country.","example:2430:exzh4":"What happens to the family of someone who has been executed?","example:2430:exzh5":"The decision to carry out an execution should be made carefully."},"2431":{"example:2431:exzh":"She won a literary award.","example:2431:exzh2":"This award is given out every year.","example:2431:exzh3":"He received an award in recognition of his efforts.","example:2431:exzh4":"The prize money was higher than I expected.","example:2431:exzh5":"She gave an acceptance speech."},"2432":{"example:2432:exzh":"He flattened the bread and made a sandwich.","example:2432:exzh2":"Work hard to stamp out wrongdoing.","example:2432:exzh3":"Dealing with crushed cans is a hassle.","example:2432:exzh4":"She hated having her dream crushed.","example:2432:exzh5":"I decided to tear down the old house."},"2433":{"example:2433:exzh":"I decided to take a break for a while.","example:2433:exzh2":"He quit his job temporarily.","example:2433:exzh3":"This problem is temporary.","example:2433:exzh4":"A temporary solution is needed.","example:2433:exzh5":"His feelings changed temporarily."},"2434":{"example:2434:exzh":"Her dream was to stand on stage.","example:2434:exzh2":"I sang on stage.","example:2434:exzh3":"A new stage begins.","example:2434:exzh4":"The stage needs to be set up.","example:2434:exzh5":"They performed on stage."},"2435":{"example:2435:exzh":"His expressiveness is wonderful.","example:2435:exzh2":"Its charm lies in the range of expression.","example:2435:exzh3":"This song has deep expressiveness.","example:2435:exzh4":"Expressing your own feelings is important.","example:2435:exzh5":"She's good at expressing herself with her body."},"2436":{"example:2436:exzh":"This information has gone through.","example:2436:exzh2":"He passed the exam.","example:2436:exzh3":"The approval process takes time.","example:2436:exzh4":"The new law has passed.","example:2436:exzh5":"The idea was approved, so the project will get started."},"2437":{"example:2437:exzh":"We need to adjust the meeting time.","example:2437:exzh2":"He adjusted the volume.","example:2437:exzh3":"Adjust the brakes to make them safer.","example:2437:exzh4":"The plan needs to be adjusted.","example:2437:exzh5":"Adjust the movement."},"2438":{"example:2438:exzh":"Please use the elevator.","example:2438:exzh2":"There are two elevators in this building.","example:2438:exzh3":"The elevator is out of order.","example:2438:exzh4":"I'll take the elevator up to the upper floor.","example:2438:exzh5":"I like riding the elevator.","grammar:2438:ex:trans":"Please use the elevator.","grammar:2438:ex:structure":"エレベーターを使ってください","grammar:2438:ex:explain":"This sentence combines a transitive verb with 「を」 and a request. The object 「エレベーター」 (elevator) takes 「を」, and the te-form of 「使う」 (use), 「使って」, plus 「ください」 makes a polite request: please use. Be careful to distinguish it from 「エスカレーター」 (escalator). The whole sentence means please use the elevator, the standard example of the 「〜を〜てください」 pattern for asking someone to do something.","grammar:2438:ex:words:0:zh":"elevator","grammar:2438:ex:words:0:note":"loanword","grammar:2438:ex:words:0:pos":"noun","grammar:2438:ex:words:1:zh":"(object marker)","grammar:2438:ex:words:1:pos":"particle","grammar:2438:ex:words:2:zh":"use","grammar:2438:ex:words:2:note":"つかって","grammar:2438:ex:words:2:pos":"verb","grammar:2438:ex:words:3:zh":"please","grammar:2438:ex:words:3:pos":"auxiliary verb","grammar:2438:ex:points:0":"❗エレベーター: elevator, lift; vs. エスカレーター (escalator).","grammar:2438:ex:points:1":"エレベーター: elevator.","grammar:2438:ex2:trans":"This building has two elevators.","grammar:2438:ex2:structure":"二つのエレベーターがあります","grammar:2438:ex2:words:0:zh":"this","grammar:2438:ex2:words:0:pos":"pre-noun adjectival","grammar:2438:ex2:words:1:zh":"building","grammar:2438:ex2:words:1:note":"loanword","grammar:2438:ex2:words:1:pos":"noun","grammar:2438:ex2:words:2:zh":"(location of existence)","grammar:2438:ex2:words:2:pos":"particle","grammar:2438:ex2:words:3:zh":"(contrast)","grammar:2438:ex2:words:3:pos":"particle","grammar:2438:ex2:words:4:zh":"two","grammar:2438:ex2:words:4:note":"ふたつ","grammar:2438:ex2:words:4:pos":"noun","grammar:2438:ex2:words:5:zh":"'s","grammar:2438:ex2:words:5:pos":"particle","grammar:2438:ex2:words:6:zh":"elevator","grammar:2438:ex2:words:6:note":"loanword","grammar:2438:ex2:words:6:pos":"noun","grammar:2438:ex2:words:7:zh":"(nominative)","grammar:2438:ex2:words:7:pos":"particle","grammar:2438:ex2:words:8:zh":"there is / are","grammar:2438:ex2:words:8:pos":"verb","grammar:2438:ex2:points:0":"❗ビル: building (short for the English word building).","grammar:2438:ex2:points:1":"ビル: building","grammar:2438:ex3:trans":"The elevator is out of order.","grammar:2438:ex3:structure":"エレベーターが故障しています","grammar:2438:ex3:words:0:zh":"elevator","grammar:2438:ex3:words:0:note":"loanword","grammar:2438:ex3:words:0:pos":"noun","grammar:2438:ex3:words:1:zh":"(nominative)","grammar:2438:ex3:words:1:pos":"particle","grammar:2438:ex3:words:2:zh":"malfunction","grammar:2438:ex3:words:2:note":"こしょうしています","grammar:2438:ex3:words:2:pos":"verb","grammar:2438:ex3:points:0":"❗故障する: break down, malfunction; エレベーターが故障 = the elevator breaks down.","grammar:2438:ex3:points:1":"故障する: break down.","grammar:2438:ex4:trans":"I take the elevator upstairs.","grammar:2438:ex4:structure":"エレベーターで上の階に行きます","grammar:2438:ex4:words:0:zh":"elevator","grammar:2438:ex4:words:0:note":"loanword","grammar:2438:ex4:words:0:pos":"noun","grammar:2438:ex4:words:1:zh":"(means)","grammar:2438:ex4:words:1:pos":"particle","grammar:2438:ex4:words:2:zh":"on top of","grammar:2438:ex4:words:2:note":"うえ","grammar:2438:ex4:words:2:pos":"noun","grammar:2438:ex4:words:3:zh":"'s","grammar:2438:ex4:words:3:pos":"particle","grammar:2438:ex4:words:4:zh":"floor","grammar:2438:ex4:words:4:note":"かい","grammar:2438:ex4:words:4:pos":"noun","grammar:2438:ex4:words:5:zh":"(destination)","grammar:2438:ex4:words:5:pos":"particle","grammar:2438:ex4:words:6:zh":"go","grammar:2438:ex4:words:6:note":"いきます","grammar:2438:ex4:words:6:pos":"verb","grammar:2438:ex4:points:0":"❗❓エレベーターで = by elevator (で marks means); 上の階 = the upper floor.","grammar:2438:ex4:points:1":"エレベーターで: by elevator.","grammar:2438:ex5:trans":"I like riding elevators.","grammar:2438:ex5:structure":"エレベーターに乗るのが好きです","grammar:2438:ex5:words:0:zh":"elevator","grammar:2438:ex5:words:0:note":"loanword","grammar:2438:ex5:words:0:pos":"noun","grammar:2438:ex5:words:1:zh":"(object)","grammar:2438:ex5:words:1:pos":"particle","grammar:2438:ex5:words:2:zh":"to ride, to board","grammar:2438:ex5:words:2:note":"のる","grammar:2438:ex5:words:2:pos":"verb","grammar:2438:ex5:words:3:zh":"(nominalizer)","grammar:2438:ex5:words:3:pos":"particle","grammar:2438:ex5:words:4:zh":"(object)","grammar:2438:ex5:words:4:pos":"particle","grammar:2438:ex5:words:5:zh":"to like","grammar:2438:ex5:words:5:note":"すき","grammar:2438:ex5:words:5:pos":"na-adjective","grammar:2438:ex5:words:6:zh":"(polite form)","grammar:2438:ex5:words:6:pos":"copula","grammar:2438:ex5:points:0":"❗〜に乗る: ride, get on…; エレベーターに乗る = ride an elevator.","grammar:2438:ex5:points:1":"エレベーターに乗る: to take the elevator."},"2439":{"example:2439:exzh":"He filed a lawsuit.","example:2439:exzh2":"Lawsuits are very complicated.","example:2439:exzh3":"The company is facing a lawsuit.","example:2439:exzh4":"We can join the lawsuit.","example:2439:exzh5":"I'm looking forward to the outcome of the lawsuit."},"2440":{"example:2440:exzh":"The machine has a malfunction.","example:2440:exzh2":"We're investigating the cause of the malfunction.","example:2440:exzh3":"The malfunction needs to be repaired.","example:2440:exzh4":"He dealt with the malfunction.","example:2440:exzh5":"If a malfunction occurs, please report it.","grammar:2440:ex:trans":"There's a malfunction in the machine.","grammar:2440:ex:structure":"機械に故障があります","grammar:2440:ex:explain":"This is an existential sentence built from 「に」 marking where something exists, plus 「が」 and 「ある」. The 「に」 in 「機械に」 points to where the fault exists — \"on the machine\" — and the subject 「故障」 takes the nominative 「が」 before 「あります」. 「故障がある」 is a set phrase meaning \"to be out of order\" or \"to break down.\" The whole sentence 「機械に故障があります」 means \"There's a malfunction in the machine,\" demonstrating the 「〜に〜がある」 pattern for saying that some condition exists in some place.","grammar:2440:ex:words:0:zh":"machine","grammar:2440:ex:words:0:note":"きかい","grammar:2440:ex:words:0:pos":"noun","grammar:2440:ex:words:1:zh":"(existence target — the one who has)","grammar:2440:ex:words:1:pos":"particle","grammar:2440:ex:words:2:zh":"malfunction","grammar:2440:ex:words:2:note":"こしょう","grammar:2440:ex:words:2:pos":"noun","grammar:2440:ex:words:3:zh":"(nominative)","grammar:2440:ex:words:3:pos":"particle","grammar:2440:ex:words:4:zh":"there is / are","grammar:2440:ex:words:4:pos":"verb","grammar:2440:ex:points:0":"❗故障（こしょう）: breakdown, fault (machines, equipment); 故障がある = to be out of order.","grammar:2440:ex:points:1":"故障: breakdown.","grammar:2440:ex2:trans":"We're investigating the cause of the breakdown.","grammar:2440:ex2:structure":"故障の原因を調べています","grammar:2440:ex2:words:0:zh":"malfunction","grammar:2440:ex2:words:0:note":"こしょう","grammar:2440:ex2:words:0:pos":"noun","grammar:2440:ex2:words:1:zh":"'s","grammar:2440:ex2:words:1:pos":"particle","grammar:2440:ex2:words:2:zh":"reason","grammar:2440:ex2:words:2:note":"げんいん","grammar:2440:ex2:words:2:pos":"noun","grammar:2440:ex2:words:3:zh":"(object marker)","grammar:2440:ex2:words:3:pos":"particle","grammar:2440:ex2:words:4:zh":"is investigating","grammar:2440:ex2:words:4:note":"しらべています","grammar:2440:ex2:words:4:pos":"verb","grammar:2440:ex2:points:0":"❗故障の原因: what caused the breakdown.","grammar:2440:ex2:points:1":"故障の原因: the cause of the breakdown.","grammar:2440:ex3:trans":"The breakdown needs to be repaired.","grammar:2440:ex3:structure":"故障を修理する必要があります","grammar:2440:ex3:words:0:zh":"malfunction","grammar:2440:ex3:words:0:note":"こしょう","grammar:2440:ex3:words:0:pos":"noun","grammar:2440:ex3:words:1:zh":"(object marker)","grammar:2440:ex3:words:1:pos":"particle","grammar:2440:ex3:words:2:zh":"repair","grammar:2440:ex3:words:2:note":"しゅうりする","grammar:2440:ex3:words:2:pos":"verb","grammar:2440:ex3:words:3:zh":"necessary","grammar:2440:ex3:words:3:note":"ひつよう","grammar:2440:ex3:words:3:pos":"noun","grammar:2440:ex3:words:4:zh":"(nominative)","grammar:2440:ex3:words:4:pos":"particle","grammar:2440:ex3:words:5:zh":"there is / are","grammar:2440:ex3:words:5:pos":"verb","grammar:2440:ex3:points:0":"❗故障を修理する: fix a breakdown, repair.","grammar:2440:ex3:points:1":"故障を修理: repair the breakdown.","grammar:2440:ex4:trans":"He dealt with the breakdown.","grammar:2440:ex4:structure":"故障の対応をしました","grammar:2440:ex4:words:0:zh":"he","grammar:2440:ex4:words:0:note":"かれ","grammar:2440:ex4:words:0:pos":"pronoun","grammar:2440:ex4:words:1:zh":"(topic)","grammar:2440:ex4:words:1:pos":"particle","grammar:2440:ex4:words:2:zh":"malfunction","grammar:2440:ex4:words:2:note":"こしょう","grammar:2440:ex4:words:2:pos":"noun","grammar:2440:ex4:words:3:zh":"'s","grammar:2440:ex4:words:3:pos":"particle","grammar:2440:ex4:words:4:zh":"deal with","grammar:2440:ex4:words:4:note":"たいおう","grammar:2440:ex4:words:4:pos":"noun","grammar:2440:ex4:words:5:zh":"(object marker)","grammar:2440:ex4:words:5:pos":"particle","grammar:2440:ex4:words:6:zh":"did","grammar:2440:ex4:words:6:pos":"verb","grammar:2440:ex4:points:0":"❗故障の対応: handling a breakdown, responding to one.","grammar:2440:ex4:points:1":"故障の対応: dealing with a breakdown.","grammar:2440:ex5:trans":"If a breakdown occurs, please report it.","grammar:2440:ex5:structure":"故障が発生したら、報告してください","grammar:2440:ex5:words:0:zh":"malfunction","grammar:2440:ex5:words:0:note":"こしょう","grammar:2440:ex5:words:0:pos":"noun","grammar:2440:ex5:words:1:zh":"(nominative)","grammar:2440:ex5:words:1:pos":"particle","grammar:2440:ex5:words:2:zh":"if it happens","grammar:2440:ex5:words:2:note":"はっせいしたら","grammar:2440:ex5:words:2:pos":"verb","grammar:2440:ex5:words:3:zh":"report","grammar:2440:ex5:words:3:note":"ほうこくして","grammar:2440:ex5:words:3:pos":"verb","grammar:2440:ex5:words:4:zh":"please","grammar:2440:ex5:words:4:pos":"auxiliary verb","grammar:2440:ex5:points:0":"❗故障が発生する: a breakdown occurs; 〜たら = if…","grammar:2440:ex5:points:1":"故障が発生: a breakdown occurs."},"2441":{"example:2441:exzh":"Try talking to him.","example:2441:exzh2":"It's hard to strike up a conversation with a stranger.","example:2441:exzh3":"She always starts conversations with the people around her.","example:2441:exzh4":"I was too shy to speak to them.","example:2441:exzh5":"Talking to friends is fun."},"2442":{"example:2442:exzh":"I like roses.","example:2442:exzh2":"She received a bouquet of roses.","example:2442:exzh3":"The scent of roses is wonderful.","example:2442:exzh4":"I bought roses so that they would celebrate for me.","example:2442:exzh5":"This rose is special."},"2443":{"example:2443:exzh":"I'm dragging luggage.","example:2443:exzh2":"He's so tired he's dragging his feet as he walks.","example:2443:exzh3":"The dog is being dragged along.","example:2443:exzh4":"You mustn't drag things out.","example:2443:exzh5":"Please don't drag this issue out."},"2444":{"example:2444:exzh":"I like buying stocks.","example:2444:exzh2":"The stock price has gone up.","example:2444:exzh3":"He's investing in stocks.","example:2444:exzh4":"Trading stocks carries risks.","example:2444:exzh5":"This stock has good prospects."},"2445":{"example:2445:exzh":"He infiltrated the enemy base.","example:2445:exzh2":"An undercover investigation is underway.","example:2445:exzh3":"That movie's theme is infiltration.","example:2445:exzh4":"I'm getting ready to infiltrate.","example:2445:exzh5":"We need an undercover investigator."},"2446":{"example:2446:exzh":"I want to go to Italy.","example:2446:exzh2":"I like Italian food.","example:2446:exzh3":"Italian culture is wonderful.","example:2446:exzh4":"I travel to Italy every year.","example:2446:exzh5":"Italy is a beautiful country.","grammar:2446:ex:trans":"I want to go to Italy.","grammar:2446:ex:structure":"イタリアに行きたいです","grammar:2446:ex:explain":"The core of this sentence is 「〜たい」 for desire plus 「に」 marking the destination. The verb 「行く」 takes 「たい」 on its continuative form to become 「行きたい」, expressing the speaker's wish to go. The 「に」 in 「イタリアに」 marks the destination of movement. 「〜たい」 conjugates like an adjective, and 「です」 can be added at the end to make it polite. The whole sentence means \"I want to go to Italy,\" a basic pattern for stating your own wishes.","grammar:2446:ex:words:0:zh":"Italy (place name)","grammar:2446:ex:words:0:pos":"noun","grammar:2446:ex:words:1:zh":"(destination)","grammar:2446:ex:words:1:pos":"particle","grammar:2446:ex:words:2:zh":"want to go","grammar:2446:ex:words:2:note":"いきたい","grammar:2446:ex:words:2:pos":"verb","grammar:2446:ex:words:3:zh":"(polite form)","grammar:2446:ex:words:3:pos":"copula","grammar:2446:ex:points:0":"❗イタリア: Italy (place name).","grammar:2446:ex:points:1":"イタリア: Italy.","grammar:2446:ex2:trans":"I like Italian food.","grammar:2446:ex2:structure":"イタリア料理が好きです","grammar:2446:ex2:words:0:zh":"Italian food","grammar:2446:ex2:words:0:note":"イタリアりょうり","grammar:2446:ex2:words:0:pos":"noun","grammar:2446:ex2:words:1:zh":"(object)","grammar:2446:ex2:words:1:pos":"particle","grammar:2446:ex2:words:2:zh":"to like","grammar:2446:ex2:words:2:note":"すき","grammar:2446:ex2:words:2:pos":"na-adjective","grammar:2446:ex2:words:3:zh":"(polite form)","grammar:2446:ex2:words:3:pos":"copula","grammar:2446:ex2:points:0":"❗イタリア料理: Italian cuisine.","grammar:2446:ex2:points:1":"イタリア料理: Italian food.","grammar:2446:ex3:trans":"Italian culture is wonderful.","grammar:2446:ex3:structure":"イタリアの文化は素晴らしいです","grammar:2446:ex3:words:0:zh":"Italy","grammar:2446:ex3:words:0:pos":"noun","grammar:2446:ex3:words:1:zh":"'s","grammar:2446:ex3:words:1:pos":"particle","grammar:2446:ex3:words:2:zh":"culture","grammar:2446:ex3:words:2:note":"ぶんか","grammar:2446:ex3:words:2:pos":"noun","grammar:2446:ex3:words:3:zh":"(topic)","grammar:2446:ex3:words:3:pos":"particle","grammar:2446:ex3:words:4:zh":"great","grammar:2446:ex3:words:4:note":"すばらしい","grammar:2446:ex3:words:4:pos":"adjective","grammar:2446:ex3:words:5:zh":"(polite form)","grammar:2446:ex3:words:5:pos":"copula","grammar:2446:ex3:points:0":"❗イタリアの文化: Italian culture.","grammar:2446:ex3:points:1":"イタリアの文化: Italian culture.","grammar:2446:ex4:trans":"I travel to Italy every year.","grammar:2446:ex4:structure":"毎年イタリアへ旅行しています","grammar:2446:ex4:words:0:zh":"every year","grammar:2446:ex4:words:0:note":"まいとし","grammar:2446:ex4:words:0:pos":"adverb","grammar:2446:ex4:words:1:zh":"Italy","grammar:2446:ex4:words:1:pos":"noun","grammar:2446:ex4:words:2:zh":"(direction)","grammar:2446:ex4:words:2:pos":"particle","grammar:2446:ex4:words:3:zh":"traveling","grammar:2446:ex4:words:3:note":"りょこうしています","grammar:2446:ex4:words:3:pos":"verb","grammar:2446:ex4:points:0":"❗〜へ旅行する: to travel to… (へ = direction).","grammar:2446:ex4:points:1":"イタリアへ旅行: travel to Italy.","grammar:2446:ex5:trans":"Italy is a beautiful country.","grammar:2446:ex5:structure":"イタリアは美しい国です","grammar:2446:ex5:words:0:zh":"Italy","grammar:2446:ex5:words:0:pos":"noun","grammar:2446:ex5:words:1:zh":"(topic)","grammar:2446:ex5:words:1:pos":"particle","grammar:2446:ex5:words:2:zh":"beautiful","grammar:2446:ex5:words:2:note":"うつくしい","grammar:2446:ex5:words:2:pos":"adjective","grammar:2446:ex5:words:3:zh":"country","grammar:2446:ex5:words:3:note":"くに","grammar:2446:ex5:words:3:pos":"noun","grammar:2446:ex5:words:4:zh":"is","grammar:2446:ex5:words:4:pos":"copula","grammar:2446:ex5:points:0":"❗美しい国: a beautiful country.","grammar:2446:ex5:points:1":"美しい国: a beautiful country."},"2447":{"example:2447:exzh":"The city has all kinds of restaurants.","example:2447:exzh2":"I live in the center of the city.","example:2447:exzh3":"I like strolling around the city.","example:2447:exzh4":"I plan to visit the city this summer.","example:2447:exzh5":"The city's transportation is very convenient."},"2448":{"example:2448:exzh":"This document needs a seal.","example:2448:exzh2":"He stamped his seal.","example:2448:exzh3":"Making a seal takes time.","example:2448:exzh4":"Not many people have a seal.","example:2448:exzh5":"Please check the seal."},"2449":{"example:2449:exzh":"He owns a huge amount of assets.","example:2449:exzh2":"Managing assets is difficult.","example:2449:exzh3":"I'm looking for ways to increase my assets.","example:2449:exzh4":"The appraised value of the assets went up.","example:2449:exzh5":"Knowledge of asset management is important."},"2450":{"example:2450:exzh":"A new construction project has started.","example:2450:exzh2":"He works at a construction company.","example:2450:exzh3":"It's important to make a construction plan.","example:2450:exzh4":"This construction is scheduled to be finished next year.","example:2450:exzh5":"The construction costs went over budget."},"2451":{"example:2451:exzh":"I wash vegetables in a colander.","example:2451:exzh2":"I put the pasta in the colander.","example:2451:exzh3":"You need a colander for cooking.","example:2451:exzh4":"I bought a new colander.","example:2451:exzh5":"I drain the water with a colander."},"2453":{"example:2453:exzh":"The correct answer is A.","example:2453:exzh2":"His answer is correct.","example:2453:exzh3":"I want to know the correct answer to the quiz.","example:2453:exzh4":"Choosing the correct answer is difficult.","example:2453:exzh5":"Please tell me the correct answer."},"2454":{"example:2454:exzh":"I was mistaken.","example:2454:exzh2":"I misunderstood what he said.","example:2454:exzh3":"This problem might cause misunderstandings.","example:2454:exzh4":"She corrected the misunderstanding.","example:2454:exzh5":"I realized it was a misunderstanding."},"2455":{"example:2455:exzh":"I was told that someone would buy a book.","example:2455:exzh2":"If you buy this, you'll be happy.","example:2455:exzh3":"A friend asked me to buy it.","example:2455:exzh4":"I wish I could buy that.","example:2455:exzh5":"Can't I get it any cheaper?","grammar:2455:ex:trans":"I was told to buy a book.","grammar:2455:ex:structure":"〜を買うと言われました","grammar:2455:ex:explain":"This sentence uses the quotative particle 「と」 plus the passive form. 「買う (to buy)」 is in the dictionary form, and 「と」 quotes the clause 「本を買う (I'll buy a book)」, which then connects to 「言われました」, the passive past of 「言う」, giving “was told to buy a book.” The passive form highlights that the speaker is the one being told. 「〜と言われる」 is the common passive quotation pattern meaning “to be told that …”.","grammar:2455:ex:words:0:zh":"book","grammar:2455:ex:words:0:note":"ほん","grammar:2455:ex:words:0:pos":"noun","grammar:2455:ex:words:1:zh":"(object marker)","grammar:2455:ex:words:1:pos":"particle","grammar:2455:ex:words:2:zh":"buy","grammar:2455:ex:words:2:note":"かう","grammar:2455:ex:words:2:pos":"verb","grammar:2455:ex:words:3:zh":"(quotation)","grammar:2455:ex:words:3:pos":"particle","grammar:2455:ex:words:4:zh":"is said","grammar:2455:ex:words:4:note":"いわれました","grammar:2455:ex:words:4:pos":"verb","grammar:2455:ex:points:0":"❗買う (かう): to buy (transitive verb); 〜と言われる = to be told that … (passive form of 言う).","grammar:2455:ex:points:1":"本を買う: to buy a book.","grammar:2455:ex2:trans":"If I can buy this, I'll be happy.","grammar:2455:ex2:structure":"〜を買えば〜になります","grammar:2455:ex2:words:0:zh":"this","grammar:2455:ex2:words:0:pos":"pronoun","grammar:2455:ex2:words:1:zh":"(object marker)","grammar:2455:ex2:words:1:pos":"particle","grammar:2455:ex2:words:2:zh":"if I buy it","grammar:2455:ex2:words:2:note":"かえば","grammar:2455:ex2:words:2:pos":"verb","grammar:2455:ex2:words:3:zh":"happy","grammar:2455:ex2:words:3:note":"しあわせ","grammar:2455:ex2:words:3:pos":"na-adjective","grammar:2455:ex2:words:4:zh":"(result)","grammar:2455:ex2:words:4:pos":"particle","grammar:2455:ex2:words:5:zh":"become","grammar:2455:ex2:words:5:pos":"verb","grammar:2455:ex2:points:0":"❗〜ば: if … (買う → 買えば); 幸せになる = to become happy.","grammar:2455:ex2:points:1":"買えば: if I buy it.","grammar:2455:ex3:trans":"A friend asked me to buy it.","grammar:2455:ex3:structure":"〜に「verb te-form」と頼まれた","grammar:2455:ex3:explain":"This sentence leaves out the person being asked, 「私」. 「友達に」 shows that the friend is the one making the request. 「買って」 is the content of the friend's request, quoted by 「と」. 「頼まれた」 is the passive past of 「頼む」, showing that I was asked to buy something; what to buy is filled in from context.","grammar:2455:ex3:words:0:zh":"friend","grammar:2455:ex3:words:0:note":"ともだち","grammar:2455:ex3:words:0:pos":"noun","grammar:2455:ex3:words:1:zh":"(the doer in a passive sentence)","grammar:2455:ex3:words:1:pos":"particle","grammar:2455:ex3:words:2:zh":"buy","grammar:2455:ex3:words:2:note":"かっ","grammar:2455:ex3:words:2:pos":"verb","grammar:2455:ex3:words:3:zh":"(casual request)","grammar:2455:ex3:words:3:pos":"particle","grammar:2455:ex3:words:4:zh":"(quotes the content of the request)","grammar:2455:ex3:words:4:pos":"particle","grammar:2455:ex3:words:5:zh":"to ask (a favor), to request","grammar:2455:ex3:words:5:note":"たのま","grammar:2455:ex3:words:5:pos":"verb","grammar:2455:ex3:words:6:zh":"(passive)","grammar:2455:ex3:words:6:pos":"auxiliary verb","grammar:2455:ex3:words:7:zh":"(past)","grammar:2455:ex3:words:7:pos":"auxiliary verb","grammar:2455:ex3:points:0":"「〜に頼まれる」 means to be asked by someone, and 「に」 marks the person making the request.","grammar:2455:ex3:points:1":"In casual speech you can make a request directly with the verb's te-form; for example, 「買って」 means “buy it for me.”","grammar:2455:ex3:points:2":"The te-form of 「買う」 is 「買って」, not 「買いて」.","grammar:2455:ex4:trans":"It would be great if I could buy that.","grammar:2455:ex4:structure":"〜を買えたらいいな","grammar:2455:ex4:words:0:zh":"that","grammar:2455:ex4:words:0:pos":"pronoun","grammar:2455:ex4:words:1:zh":"(object marker)","grammar:2455:ex4:words:1:pos":"particle","grammar:2455:ex4:words:2:zh":"if I could buy it","grammar:2455:ex4:words:2:note":"かえたら","grammar:2455:ex4:words:2:pos":"verb","grammar:2455:ex4:words:3:zh":"good","grammar:2455:ex4:words:3:pos":"adjective","grammar:2455:ex4:words:4:zh":"(exclamation)","grammar:2455:ex4:words:4:pos":"particle","grammar:2455:ex4:points:0":"❗〜たらいいな: it would be nice if … (買える = can buy, potential form).","grammar:2455:ex4:points:1":"買えたらいいな: I wish I could buy it.","grammar:2455:ex5:trans":"Could I get it cheaper?","grammar:2455:ex5:structure":"もっと安く買えませんか","grammar:2455:ex5:words:0:zh":"more","grammar:2455:ex5:words:0:pos":"adverb","grammar:2455:ex5:words:1:zh":"cheaply","grammar:2455:ex5:words:1:note":"やすく","grammar:2455:ex5:words:1:pos":"adjective","grammar:2455:ex5:words:2:zh":"can't buy","grammar:2455:ex5:words:2:note":"かえません","grammar:2455:ex5:words:2:pos":"verb","grammar:2455:ex5:words:3:zh":"(question)","grammar:2455:ex5:words:3:pos":"particle","grammar:2455:ex5:points:0":"❗安く: cheaply (安い → 安く); 買えませんか = can't I buy? (negative potential question, a polite request).","grammar:2455:ex5:points:1":"安く買える: to buy cheaply.","exam:2455:zh":"I decided to pay at the store and buy the book.","exam:2455:why":"Paying money to get an item is 「買う」. The other verbs can't take a book as their object."},"2456":{"example:2456:exzh":"He is in the navy.","example:2456:exzh2":"Naval training is being conducted.","example:2456:exzh3":"The navy protects the nation's security.","example:2456:exzh4":"She is drawn to the navy.","example:2456:exzh5":"The history of the navy is interesting."},"2457":{"example:2457:exzh":"This product comes with a gift.","grammar:2457:ex:trans":"This product comes with a free gift.","grammar:2457:ex:structure":"この商品には + プレゼントが + 付いています","grammar:2457:ex:explain":"「付く」 can mean that something is attached to a place, and it can also mean that a product or service comes with something. In this sentence, 「プレゼントが付いています」 does not mean a gift is being stuck on right now; it means the product comes with a gift. When you study it, it helps to learn 「名詞に物が付く」 as a common pattern.","grammar:2457:ex:words:0:zh":"this","grammar:2457:ex:words:0:pos":"pre-noun adjectival","grammar:2457:ex:words:1:zh":"product","grammar:2457:ex:words:1:note":"しょうひん；商品","grammar:2457:ex:words:1:pos":"noun","grammar:2457:ex:words:2:zh":"in, as for","grammar:2457:ex:words:2:pos":"particle","grammar:2457:ex:words:3:zh":"marks the topic","grammar:2457:ex:words:3:pos":"particle","grammar:2457:ex:words:4:zh":"free gift","grammar:2457:ex:words:4:pos":"noun","grammar:2457:ex:words:5:zh":"marks the subject","grammar:2457:ex:words:5:pos":"particle","grammar:2457:ex:words:6:zh":"to be attached, to come with","grammar:2457:ex:words:6:note":"ついて; the te-form of 付く","grammar:2457:ex:words:6:pos":"verb","grammar:2457:ex:words:7:zh":"is in a certain state","grammar:2457:ex:words:7:pos":"auxiliary verb","grammar:2457:ex:words:8:zh":"polite ending","grammar:2457:ex:words:8:pos":"auxiliary verb","grammar:2457:ex:points:0":"「付いています」 shows that the gift is attached to the product, or that the product comes with a gift.","grammar:2457:ex:points:1":"「には」 picks out 「この商品」 as the thing being described.","grammar:2457:ex:points:2":"「が」 marks the thing actually included, namely the gift."},"2458":{"example:2458:exzh":"He is burdened with a large debt."},"2459":{"example:2459:exzh":"Please knock before you come in."},"2460":{"example:2460:exzh":"He is drafting an official document."},"2461":{"example:2461:exzh":"The chairperson opened the meeting."},"2462":{"example:2462:exzh":"I usually get up earlier."},"2463":{"example:2463:exzh":"She posts on social media."},"2464":{"example:2464:exzh":"I borrowed a book at the library."},"2465":{"example:2465:exzh":"Rob likes new movies."},"2466":{"example:2466:exzh":"Okay, let's go.","grammar:2466:ex:trans":"OK, let's go.","grammar:2466:ex:structure":"OK, let's go.","grammar:2466:ex:explain":"The core of this sentence is the volitional form 「〜ましょう」. The opening 「オーケイ」 (OK, all right) is a casual way to agree, the same as 「いいよ／わかった」. 「行きましょう」 is the 「〜ましょう」 form of 「行く」, offering or suggesting let's … together. The whole sentence means OK, let's go, showing how 「〜ましょう」 invites the other person to act together, with a positive, friendly tone.","grammar:2466:ex:words:0:zh":"good","grammar:2466:ex:words:0:note":"loanword","grammar:2466:ex:words:0:pos":"interjection","grammar:2466:ex:words:1:zh":"let's go","grammar:2466:ex:words:1:note":"いきましょう","grammar:2466:ex:words:1:pos":"verb","grammar:2466:ex:points:0":"❗オーケイ: OK, no problem (casual agreement, the same as 「いいよ／わかった」).","grammar:2466:ex:points:1":"オーケイ: OK."},"2467":{"example:2467:exzh":"A baby's skin is very soft.","example:2467:exzh2":"The skin trouble continues.","example:2467:exzh3":"This cream can be used even on sensitive skin.","example:2467:exzh4":"I put on sunscreen to protect my skin.","example:2467:exzh5":"I consulted a dermatologist about my symptoms."},"2469":{"example:2469:exzh":"The results of this project are starting to show.","example:2469:exzh2":"Please show me the results of his efforts.","example:2469:exzh3":"It's time to report the results.","example:2469:exzh4":"Our team's results were recognized.","example:2469:exzh5":"The results exceeded expectations."},"2470":{"example:2470:exzh":"He fled from the police.","example:2470:exzh2":"He tried to escape, but was caught.","example:2470:exzh3":"His escape was a surprise.","example:2470:exzh4":"The escaped criminal was found.","example:2470:exzh5":"Making an escape plan isn't easy."},"2471":{"example:2471:exzh":"She feels sadness.","example:2471:exzh2":"Getting over sadness is difficult.","example:2471:exzh3":"There's a hint of sadness in his story.","example:2471:exzh4":"Sharing sadness is important.","example:2471:exzh5":"I want to find a way to express my sadness."},"2472":{"example:2472:exzh":"The chief opened the meeting.","example:2472:exzh2":"He was appointed as the new chief.","example:2472:exzh3":"I received guidance from the chief.","example:2472:exzh4":"The chief is busy with work.","example:2472:exzh5":"The chief made a decision."},"2473":{"example:2473:exzh":"His business recovered.","example:2473:exzh2":"Easter is an important day in Christianity.","example:2473:exzh3":"The old festival in this village was revived for the first time in thirty years.","example:2473:exzh4":"Resurrection from death is mysterious.","example:2473:exzh5":"I helped his heart recover."},"2474":{"example:2474:exzh":"He stuck out his tongue.","example:2474:exzh2":"You need to be careful when your tongue hurts.","example:2474:exzh3":"Looking at the tongue tells you its condition.","example:2474:exzh4":"I've bitten my tongue before.","example:2474:exzh5":"When your tongue gets burned, drink water."},"2477":{"example:2477:exzh":"The cold symptoms are getting worse.","example:2477:exzh2":"His symptoms need a diagnosis.","example:2477:exzh3":"A new symptom appeared.","example:2477:exzh4":"If the symptoms continue, please go to the hospital.","example:2477:exzh5":"She explained her symptoms."},"2478":{"example:2478:exzh":"Hundreds of people are gathered.","example:2478:exzh2":"He has a few hundred yen on him.","example:2478:exzh3":"This project has hundreds of participants.","example:2478:exzh4":"I practiced hundreds of times.","example:2478:exzh5":"There are hundreds of options.","grammar:2478:ex:trans":"Hundreds of people are gathered.","grammar:2478:ex:structure":"Hundreds of people are gathered.","grammar:2478:ex:explain":"This sentence uses the subject marker 「が」 plus 「〜ている」 to describe a state. The subject 「数百人」 (several hundred people) takes the subject marker 「が」, and 「数百」 means hundreds, several hundred. The verb 「集まる」 (to gather) is an intransitive verb, and 「〜ている」 in 「集まっています」 describes the ongoing state of being gathered, that is, gathered together. The whole sentence means hundreds of people are gathered; here 「が」 presents the subject as new information right in front of you, describing the scene.","grammar:2478:ex:words:0:zh":"hundreds of people","grammar:2478:ex:words:0:note":"すうひゃくにん","grammar:2478:ex:words:0:pos":"noun","grammar:2478:ex:words:1:zh":"(nominative)","grammar:2478:ex:words:1:pos":"particle","grammar:2478:ex:words:2:zh":"are gathered","grammar:2478:ex:words:2:note":"あつまっています","grammar:2478:ex:words:2:pos":"verb","grammar:2478:ex:points:0":"❗数百（すうひゃく）: hundreds, several hundred; 数百人 = several hundred people.","grammar:2478:ex:points:1":"数百: hundreds.","grammar:2478:ex2:trans":"He has a few hundred yen on him.","grammar:2478:ex2:structure":"He has a few hundred yen.","grammar:2478:ex2:words:0:zh":"he","grammar:2478:ex2:words:0:note":"かれ","grammar:2478:ex2:words:0:pos":"pronoun","grammar:2478:ex2:words:1:zh":"(topic)","grammar:2478:ex2:words:1:pos":"particle","grammar:2478:ex2:words:2:zh":"a few hundred yen","grammar:2478:ex2:words:2:note":"すうひゃくえん","grammar:2478:ex2:words:2:pos":"noun","grammar:2478:ex2:words:3:zh":"(object marker)","grammar:2478:ex2:words:3:pos":"particle","grammar:2478:ex2:words:4:zh":"to have","grammar:2478:ex2:words:4:note":"もっています","grammar:2478:ex2:words:4:pos":"verb","grammar:2478:ex2:points:0":"❗数百円: a few hundred yen (small change).","grammar:2478:ex2:points:1":"数百円: a few hundred yen.","grammar:2478:ex3:trans":"This project has hundreds of participants.","grammar:2478:ex3:structure":"there are hundreds of participants","grammar:2478:ex3:words:0:zh":"this","grammar:2478:ex3:words:0:pos":"pre-noun adjectival","grammar:2478:ex3:words:1:zh":"project","grammar:2478:ex3:words:1:note":"loanword","grammar:2478:ex3:words:1:pos":"noun","grammar:2478:ex3:words:2:zh":"(existence target — the one who has)","grammar:2478:ex3:words:2:pos":"particle","grammar:2478:ex3:words:3:zh":"(contrast)","grammar:2478:ex3:words:3:pos":"particle","grammar:2478:ex3:words:4:zh":"hundreds","grammar:2478:ex3:words:4:note":"すうひゃく","grammar:2478:ex3:words:4:pos":"noun","grammar:2478:ex3:words:5:zh":"'s","grammar:2478:ex3:words:5:pos":"particle","grammar:2478:ex3:words:6:zh":"participants","grammar:2478:ex3:words:6:note":"さんかしゃ","grammar:2478:ex3:words:6:pos":"noun","grammar:2478:ex3:words:7:zh":"(nominative)","grammar:2478:ex3:words:7:pos":"particle","grammar:2478:ex3:words:8:zh":"there is / are","grammar:2478:ex3:words:8:pos":"verb","grammar:2478:ex3:points:0":"❗数百の参加者: hundreds of participants.","grammar:2478:ex3:points:1":"数百の参加者: hundreds of people.","grammar:2478:ex4:trans":"I practiced hundreds of times.","grammar:2478:ex4:structure":"practiced hundreds of times","grammar:2478:ex4:words:0:zh":"hundreds of times","grammar:2478:ex4:words:0:note":"すうひゃっかい","grammar:2478:ex4:words:0:pos":"noun","grammar:2478:ex4:words:1:zh":"as much as","grammar:2478:ex4:words:1:pos":"particle","grammar:2478:ex4:words:2:zh":"practiced","grammar:2478:ex4:words:2:note":"れんしゅうしました","grammar:2478:ex4:words:2:pos":"verb","grammar:2478:ex4:points:0":"❗数百回も: as many as hundreds of times (も for emphasis).","grammar:2478:ex4:points:1":"数百回も: up to hundreds of times.","grammar:2478:ex5:trans":"There are hundreds of options.","grammar:2478:ex5:structure":"there are hundreds of options","grammar:2478:ex5:words:0:zh":"hundreds","grammar:2478:ex5:words:0:note":"すうひゃく","grammar:2478:ex5:words:0:pos":"noun","grammar:2478:ex5:words:1:zh":"'s","grammar:2478:ex5:words:1:pos":"particle","grammar:2478:ex5:words:2:zh":"option","grammar:2478:ex5:words:2:note":"せんたくし","grammar:2478:ex5:words:2:pos":"noun","grammar:2478:ex5:words:3:zh":"(nominative)","grammar:2478:ex5:words:3:pos":"particle","grammar:2478:ex5:words:4:zh":"there is / are","grammar:2478:ex5:words:4:pos":"verb","grammar:2478:ex5:points:0":"❗数百の選択肢: hundreds of choices.","grammar:2478:ex5:points:1":"数百の選択肢: hundreds of options."},"2479":{"example:2479:exzh":"Her turn is next week.","example:2479:exzh2":"I can't wait for my turn.","example:2479:exzh3":"This is my turn.","example:2479:exzh4":"Let's get ready for our turn.","example:2479:exzh5":"My turn has come!"},"2480":{"example:2480:exzh":"Saturday is a day off.","example:2480:exzh2":"Let's meet this Saturday.","example:2480:exzh3":"I go jogging on Saturday mornings.","example:2480:exzh4":"He hangs out with his friends on Saturday.","example:2480:exzh5":"I watch movies on Saturday nights.","grammar:2480:ex:trans":"Saturday is a day off.","grammar:2480:ex:structure":"Saturday is a day off.","grammar:2480:ex:explain":"This is the simplest kind of AはBです statement. The topic 「土曜」 (Saturday) takes 「は」, and the predicate 「休み」 (rest, a day off) is a noun, judged with 「です」. 「土曜」 is a shortened form of 「土曜日」, with 「土」 taken from one of the seven days of the week. The whole sentence means Saturday is a day off, showing how 「〜は〜です」 links a day with its attribute — a common way to talk about your schedule.","grammar:2480:ex:words:0:zh":"Saturday","grammar:2480:ex:words:0:note":"どよう","grammar:2480:ex:words:0:pos":"noun","grammar:2480:ex:words:1:zh":"(topic)","grammar:2480:ex:words:1:pos":"particle","grammar:2480:ex:words:2:zh":"rest","grammar:2480:ex:words:2:note":"やすみ","grammar:2480:ex:words:2:pos":"noun","grammar:2480:ex:words:3:zh":"is","grammar:2480:ex:words:3:pos":"copula","grammar:2480:ex:points:1":"土曜: Saturday.","grammar:2480:ex2:trans":"Let's meet this Saturday.","grammar:2480:ex2:structure":"Let's meet this Saturday.","grammar:2480:ex2:words:0:zh":"this week","grammar:2480:ex2:words:0:note":"こんしゅう","grammar:2480:ex2:words:0:pos":"noun","grammar:2480:ex2:words:1:zh":"'s","grammar:2480:ex2:words:1:pos":"particle","grammar:2480:ex2:words:2:zh":"Saturday","grammar:2480:ex2:words:2:note":"どよう","grammar:2480:ex2:words:2:pos":"noun","grammar:2480:ex2:words:3:zh":"(point in time)","grammar:2480:ex2:words:3:pos":"particle","grammar:2480:ex2:words:4:zh":"let's meet","grammar:2480:ex2:words:4:note":"あいましょう","grammar:2480:ex2:words:4:pos":"verb","grammar:2480:ex2:points:0":"❗今週の土曜: this Saturday.","grammar:2480:ex2:points:1":"今週の土曜: this Saturday.","grammar:2480:ex3:trans":"I go jogging on Saturday mornings.","grammar:2480:ex3:structure":"I go jogging on Saturday morning.","grammar:2480:ex3:words:0:zh":"Saturday","grammar:2480:ex3:words:0:note":"どよう","grammar:2480:ex3:words:0:pos":"noun","grammar:2480:ex3:words:1:zh":"'s","grammar:2480:ex3:words:1:pos":"particle","grammar:2480:ex3:words:2:zh":"morning","grammar:2480:ex3:words:2:note":"あさ","grammar:2480:ex3:words:2:pos":"noun","grammar:2480:ex3:words:3:zh":"(point in time)","grammar:2480:ex3:words:3:pos":"particle","grammar:2480:ex3:words:4:zh":"jogging","grammar:2480:ex3:words:4:pos":"verb","grammar:2480:ex3:points:0":"❗ジョギング: jogging.","grammar:2480:ex3:points:1":"ジョギング: jogging.","grammar:2480:ex4:trans":"He hangs out with friends on Saturdays.","grammar:2480:ex4:structure":"hangs out with friends on Saturday","grammar:2480:ex4:words:0:zh":"he","grammar:2480:ex4:words:0:note":"かれ","grammar:2480:ex4:words:0:pos":"pronoun","grammar:2480:ex4:words:1:zh":"(topic)","grammar:2480:ex4:words:1:pos":"particle","grammar:2480:ex4:words:2:zh":"Saturday","grammar:2480:ex4:words:2:note":"どよう","grammar:2480:ex4:words:2:pos":"noun","grammar:2480:ex4:words:3:zh":"(point in time)","grammar:2480:ex4:words:3:pos":"particle","grammar:2480:ex4:words:4:zh":"friend","grammar:2480:ex4:words:4:note":"ともだち","grammar:2480:ex4:words:4:pos":"noun","grammar:2480:ex4:words:5:zh":"(object)","grammar:2480:ex4:words:5:pos":"particle","grammar:2480:ex4:words:6:zh":"hang out","grammar:2480:ex4:words:6:note":"あそびます","grammar:2480:ex4:words:6:pos":"verb","grammar:2480:ex4:points:0":"❗土曜に遊ぶ: to go out and have fun on Saturday.","grammar:2480:ex4:points:1":"土曜に: on Saturday.","grammar:2480:ex5:trans":"I watch a movie on Saturday night.","grammar:2480:ex5:structure":"I watch a movie on Saturday night.","grammar:2480:ex5:words:0:zh":"Saturday","grammar:2480:ex5:words:0:note":"どよう","grammar:2480:ex5:words:0:pos":"noun","grammar:2480:ex5:words:1:zh":"'s","grammar:2480:ex5:words:1:pos":"particle","grammar:2480:ex5:words:2:zh":"evening","grammar:2480:ex5:words:2:note":"ばん","grammar:2480:ex5:words:2:pos":"noun","grammar:2480:ex5:words:3:zh":"(topic)","grammar:2480:ex5:words:3:pos":"particle","grammar:2480:ex5:words:4:zh":"movie","grammar:2480:ex5:words:4:note":"えいが","grammar:2480:ex5:words:4:pos":"noun","grammar:2480:ex5:words:5:zh":"(object marker)","grammar:2480:ex5:words:5:pos":"particle","grammar:2480:ex5:words:6:zh":"look","grammar:2480:ex5:words:6:note":"みます","grammar:2480:ex5:words:6:pos":"verb","grammar:2480:ex5:points:0":"❗土曜の晩: Saturday night (晩 = evening, night).","grammar:2480:ex5:points:1":"土曜の晩: Saturday night.","exam:2480:zh":"The day after Friday is Saturday.","exam:2480:why":"「土曜」 is Saturday, which comes after Friday. 「木曜」 is Thursday, which comes before Friday."},"2481":{"example:2481:exzh":"His conviction is strong.","example:2481:exzh2":"It's important to have conviction.","example:2481:exzh3":"My conviction won't change.","example:2481:exzh4":"I will act according to my beliefs.","example:2481:exzh5":"Her beliefs are respected."},"2482":{"example:2482:exzh":"I went to bed late last night.","example:2482:exzh2":"Last night's party was fun.","example:2482:exzh3":"I watched a movie last night.","example:2482:exzh4":"Last night's news was surprising.","example:2482:exzh5":"I chatted with a friend last night."},"2483":{"example:2483:exzh":"There is progress on the project.","example:2483:exzh2":"His research is making progress.","example:2483:exzh3":"Please let me know if there is any progress.","example:2483:exzh4":"Progress has been delayed.","example:2483:exzh5":"I'm looking forward to progress."},"2484":{"example:2484:exzh":"This seat is very comfortable.","example:2484:exzh2":"Sit in a bus seat.","example:2484:exzh3":"Adjust the car seat.","example:2484:exzh4":"I bought a new seat.","example:2484:exzh5":"Please fasten your seatbelt."},"2485":{"example:2485:exzh":"I gave a friend some advice.","example:2485:exzh2":"Listen to an expert's advice.","example:2485:exzh3":"I want good advice.","example:2485:exzh4":"I will follow his advice.","example:2485:exzh5":"Thank you for your advice."},"2486":{"example:2486:exzh":"May I accept this gift?","example:2486:exzh2":"Could you tell me?","example:2486:exzh3":"I'd be happy to receive everyone's opinions.","example:2486:exzh4":"Could I have your help?","example:2486:exzh5":"It would be a big help if you could give me some advice."},"2487":{"example:2487:exzh":"Please submit by this deadline.","example:2487:exzh2":"The research deadline is approaching.","example:2487:exzh3":"I'm looking forward to the next term.","example:2487:exzh4":"How many weeks of classes are there in this term?","example:2487:exzh5":"Take vacation during this period."},"2488":{"example:2488:exzh":"He was arrested for assault.","example:2488:exzh2":"Assault cases are increasing.","example:2488:exzh3":"Assault is an unacceptable act.","example:2488:exzh4":"It is necessary to consider the impact of assault.","example:2488:exzh5":"She is a victim of assault."},"2489":{"example:2489:exzh":"Let's try this for now.","example:2489:exzh2":"Let's have some tea for now.","example:2489:exzh3":"Let's hold a meeting and talk for now.","example:2489:exzh4":"Let's rest for now.","example:2489:exzh5":"Please wait here for now."},"2490":{"example:2490:exzh":"His words drew laughter.","example:2490:exzh2":"The laughter won't stop.","example:2490:exzh3":"That movie gets laughs.","example:2490:exzh4":"Everyone's laughter wouldn't stop.","example:2490:exzh5":"Laughter lightens the heart.","grammar:2490:ex:trans":"His words drew laughter.","grammar:2490:ex:structure":"話に笑いが起きた","grammar:2490:ex:explain":"This sentence is built as 「に」 plus 「が」 plus an intransitive verb. In 「彼の話に」, 「に」 marks the source or trigger, meaning because of his words; the subject 「笑い」 (laughter) takes the subject marker 「が」 and is the noun form of 「笑う」. The verb 「起きる」 (to arise, to occur) appears in the past form 「起きた」. 「笑いが起きる」 is a set way of saying that laughter breaks out. The whole sentence means: His words drew laughter.","grammar:2490:ex:words:0:zh":"he","grammar:2490:ex:words:0:note":"かれ","grammar:2490:ex:words:0:pos":"pronoun","grammar:2490:ex:words:1:zh":"'s","grammar:2490:ex:words:1:pos":"particle","grammar:2490:ex:words:2:zh":"talk; story","grammar:2490:ex:words:2:note":"はなし","grammar:2490:ex:words:2:pos":"noun","grammar:2490:ex:words:3:zh":"(object)","grammar:2490:ex:words:3:pos":"particle","grammar:2490:ex:words:4:zh":"laughter","grammar:2490:ex:words:4:note":"わらい","grammar:2490:ex:words:4:pos":"noun","grammar:2490:ex:words:5:zh":"(nominative)","grammar:2490:ex:words:5:pos":"particle","grammar:2490:ex:words:6:zh":"caused","grammar:2490:ex:words:6:note":"おきた","grammar:2490:ex:words:6:pos":"verb","grammar:2490:ex:points:0":"❗笑い（わらい）: a laugh, laughter (the noun form of 笑う); 笑いが起きる = laughter breaks out.","grammar:2490:ex:points:1":"笑い: laughter.","grammar:2490:ex2:trans":"The laughter won't stop.","grammar:2490:ex2:structure":"笑いが止まらない","grammar:2490:ex2:words:0:zh":"laughter","grammar:2490:ex2:words:0:note":"わらい","grammar:2490:ex2:words:0:pos":"noun","grammar:2490:ex2:words:1:zh":"(nominative)","grammar:2490:ex2:words:1:pos":"particle","grammar:2490:ex2:words:2:zh":"won't stop","grammar:2490:ex2:words:2:note":"とまらない","grammar:2490:ex2:words:2:pos":"verb","grammar:2490:ex2:points:0":"❗笑いが止まらない: can't stop laughing (the negative of the intransitive verb 止まる).","grammar:2490:ex2:points:1":"笑いが止まらない: the laughter won't stop.","grammar:2490:ex3:trans":"That movie is really funny.","grammar:2490:ex3:structure":"その映画は笑いを取る","grammar:2490:ex3:words:0:zh":"that","grammar:2490:ex3:words:0:pos":"pre-noun adjectival","grammar:2490:ex3:words:1:zh":"movie","grammar:2490:ex3:words:1:note":"えいが","grammar:2490:ex3:words:1:pos":"noun","grammar:2490:ex3:words:2:zh":"(topic)","grammar:2490:ex3:words:2:pos":"particle","grammar:2490:ex3:words:3:zh":"smile","grammar:2490:ex3:words:3:note":"わらい","grammar:2490:ex3:words:3:pos":"noun","grammar:2490:ex3:words:4:zh":"(object marker)","grammar:2490:ex3:words:4:pos":"particle","grammar:2490:ex3:words:5:zh":"to get laughs","grammar:2490:ex3:words:5:note":"とる","grammar:2490:ex3:words:5:pos":"verb","grammar:2490:ex3:points:0":"❗笑いを取る: to get a laugh, to win laughter (a set expression; 取る = to win).","grammar:2490:ex3:points:1":"笑いを取る: to get a laugh.","grammar:2490:ex4:trans":"Everyone's laughter wouldn't stop.","grammar:2490:ex4:structure":"〜の笑いが止まりませんでした","grammar:2490:ex4:explain":"「みんなの笑い」 is everyone's laughter, marked with 「が」 as the subject of 「止まる」. 「止まる」 is an intransitive verb, and 「止まりませんでした」 literally means it did not stop at that time, which in this situation naturally means everyone kept laughing and the laughter wouldn't stop.","grammar:2490:ex4:words:0:zh":"everyone","grammar:2490:ex4:words:0:pos":"pronoun","grammar:2490:ex4:words:1:zh":"(possession / modification)","grammar:2490:ex4:words:1:pos":"particle","grammar:2490:ex4:words:2:zh":"laughter, a laugh","grammar:2490:ex4:words:2:note":"わらい","grammar:2490:ex4:words:2:pos":"noun","grammar:2490:ex4:words:3:zh":"(nominative)","grammar:2490:ex4:words:3:pos":"particle","grammar:2490:ex4:words:4:zh":"stop","grammar:2490:ex4:words:4:note":"とまり","grammar:2490:ex4:words:4:pos":"verb","grammar:2490:ex4:words:5:zh":"(polite tone)","grammar:2490:ex4:words:5:pos":"auxiliary verb","grammar:2490:ex4:words:6:zh":"(negative)","grammar:2490:ex4:words:6:pos":"auxiliary verb","grammar:2490:ex4:words:7:zh":"(part of the polite past form)","grammar:2490:ex4:words:7:pos":"auxiliary verb","grammar:2490:ex4:words:8:zh":"(past)","grammar:2490:ex4:words:8:pos":"auxiliary verb","grammar:2490:ex4:points:0":"「ませんでした」 is the polite past negative, meaning it did not stop at that time.","grammar:2490:ex4:points:1":"Here 「笑い」 is a noun meaning laughter or a laugh.","grammar:2490:ex5:trans":"Laughter lightens the heart.","grammar:2490:ex5:structure":"笑いは心を軽くする","grammar:2490:ex5:words:0:zh":"smile","grammar:2490:ex5:words:0:note":"わらい","grammar:2490:ex5:words:0:pos":"noun","grammar:2490:ex5:words:1:zh":"(topic)","grammar:2490:ex5:words:1:pos":"particle","grammar:2490:ex5:words:2:zh":"heart","grammar:2490:ex5:words:2:note":"こころ","grammar:2490:ex5:words:2:pos":"noun","grammar:2490:ex5:words:3:zh":"(object marker)","grammar:2490:ex5:words:3:pos":"particle","grammar:2490:ex5:words:4:zh":"to lighten","grammar:2490:ex5:words:4:note":"かるくする","grammar:2490:ex5:words:4:pos":"adjective","grammar:2490:ex5:points:0":"❗心を軽くする: to lighten the heart, to put someone at ease (軽くする = to make light).","grammar:2490:ex5:points:1":"心を軽くする: to put the heart at ease."},"2491":{"example:2491:exzh":"I choose clothes that look good.","example:2491:exzh2":"The look is changing.","example:2491:exzh3":"A new look is in fashion.","example:2491:exzh4":"I care a lot about how things look.","example:2491:exzh5":"I like his look."},"2492":{"example:2492:exzh":"We will move forward toward a new goal.","example:2492:exzh2":"I got lost along the way as we moved forward.","example:2492:exzh3":"He wants to advance his career at the company.","example:2492:exzh4":"The team keeps moving forward in the match.","example:2492:exzh5":"We move forward toward the future."},"2493":{"example:2493:exzh":"A strong vibration came from the old machine.","example:2493:exzh2":"This guitar has a strong vibration.","example:2493:exzh3":"The pendulum vibrates at regular intervals.","example:2493:exzh5":"I felt a slight vibration inside the car."},"2494":{"example:2494:exzh":"Next week, I'm moving to a new house.","example:2494:exzh2":"Moving is a hassle, but I'm looking forward to it.","example:2494:exzh3":"He is planning to move to Tokyo.","example:2494:exzh4":"The preparations for moving are almost done.","example:2494:exzh5":"A friend helped me when I moved.","grammar:2494:ex:trans":"Next week I'm moving to a new house.","grammar:2494:ex:structure":"〜に引っ越します","grammar:2494:ex:explain":"This sentence uses 「に」 for the destination together with an intransitive verb. The time word 「来週 (next week)」 sets the time, the topic 「私」 takes 「は」, and the 「に」 in 「新しい家に」 marks the destination of the move, “to a new house.” The verb 「引っ越す (to move house)」 is an intransitive verb, and the polite 「引っ越します」 expresses a future plan. The whole sentence means “next week I'm moving to a new house,” showing how a moving-type intransitive verb uses 「に」 to introduce the new place.","grammar:2494:ex:words:0:zh":"next week","grammar:2494:ex:words:0:note":"らいしゅう","grammar:2494:ex:words:0:pos":"noun","grammar:2494:ex:words:1:zh":"I","grammar:2494:ex:words:1:note":"わたし","grammar:2494:ex:words:1:pos":"pronoun","grammar:2494:ex:words:2:zh":"(topic)","grammar:2494:ex:words:2:pos":"particle","grammar:2494:ex:words:3:zh":"new","grammar:2494:ex:words:3:note":"あたらしい","grammar:2494:ex:words:3:pos":"adjective","grammar:2494:ex:words:4:zh":"house","grammar:2494:ex:words:4:note":"いえ","grammar:2494:ex:words:4:pos":"noun","grammar:2494:ex:words:5:zh":"(the destination point)","grammar:2494:ex:words:5:pos":"particle","grammar:2494:ex:words:6:zh":"to move house","grammar:2494:ex:words:6:note":"ひっこします","grammar:2494:ex:words:6:pos":"verb","grammar:2494:ex:points:0":"❗引っ越す (ひっこす): to move house (intransitive verb); 〜に引っ越す = to move to …","grammar:2494:ex:points:1":"家に引っ越す: to move to a new home.","grammar:2494:ex2:trans":"Moving is a hassle, but I'm looking forward to it.","grammar:2494:ex2:structure":"verb dictionary form＋のは〜だけど、楽しみです","grammar:2494:ex2:explain":"「引っ越すのは」 brings up the act of moving as the topic. 「大変だけど」 acknowledges that moving is hard, and then 「楽しみです」 adds that you're looking forward to it; here 「楽しみ」 means anticipating what's coming.","grammar:2494:ex2:words:0:zh":"to move house","grammar:2494:ex2:words:0:note":"ひっこす","grammar:2494:ex2:words:0:pos":"verb","grammar:2494:ex2:words:1:zh":"(nominalizes the action)","grammar:2494:ex2:words:1:pos":"particle","grammar:2494:ex2:words:2:zh":"(topic)","grammar:2494:ex2:words:2:pos":"particle","grammar:2494:ex2:words:3:zh":"hard, a hassle","grammar:2494:ex2:words:3:note":"たいへん","grammar:2494:ex2:words:3:pos":"na-adjective","grammar:2494:ex2:words:4:zh":"(plain-form judgment)","grammar:2494:ex2:words:4:pos":"auxiliary verb","grammar:2494:ex2:words:5:zh":"(contrast) but","grammar:2494:ex2:words:5:pos":"particle","grammar:2494:ex2:words:6:zh":"look forward to","grammar:2494:ex2:words:6:note":"たのしみ","grammar:2494:ex2:words:6:pos":"noun","grammar:2494:ex2:words:7:zh":"(polite statement)","grammar:2494:ex2:words:7:pos":"auxiliary verb","grammar:2494:ex2:points:0":"「引っ越すの」 uses 「の」 to turn the action of moving into something you can talk about.","grammar:2494:ex2:points:1":"「大変だけど」 shows that although it's hard or troublesome, there is another feeling as well.","grammar:2494:ex2:points:2":"「楽しみです」 expresses looking forward to something, which is different from 「楽しいです」, which means fun.","grammar:2494:ex3:trans":"He is planning to move to Tokyo.","grammar:2494:ex3:structure":"〜に引っ越すことを計画しています","grammar:2494:ex3:explain":"「東京に引っ越すこと」 refers to the act of moving to Tokyo, and the 「を」 after it marks the whole phrase as the content of the plan. 「計画しています」 means he is planning it now; it does not mean he has already moved to Tokyo.","grammar:2494:ex3:words:0:zh":"he","grammar:2494:ex3:words:0:note":"かれ","grammar:2494:ex3:words:0:pos":"pronoun","grammar:2494:ex3:words:1:zh":"(topic)","grammar:2494:ex3:words:1:pos":"particle","grammar:2494:ex3:words:2:zh":"Tokyo","grammar:2494:ex3:words:2:note":"とうきょう","grammar:2494:ex3:words:2:pos":"noun","grammar:2494:ex3:words:3:zh":"(destination of the move)","grammar:2494:ex3:words:3:pos":"particle","grammar:2494:ex3:words:4:zh":"to move house","grammar:2494:ex3:words:4:note":"ひっこす","grammar:2494:ex3:words:4:pos":"verb","grammar:2494:ex3:words:5:zh":"matter (turns the action into a noun)","grammar:2494:ex3:words:5:pos":"noun","grammar:2494:ex3:words:6:zh":"(object)","grammar:2494:ex3:words:6:pos":"particle","grammar:2494:ex3:words:7:zh":"plan","grammar:2494:ex3:words:7:note":"けいかく","grammar:2494:ex3:words:7:pos":"noun","grammar:2494:ex3:words:8:zh":"carry out","grammar:2494:ex3:words:8:pos":"verb","grammar:2494:ex3:words:9:zh":"(links to the ongoing expression that follows)","grammar:2494:ex3:words:9:pos":"particle","grammar:2494:ex3:words:10:zh":"in progress","grammar:2494:ex3:words:10:pos":"verb","grammar:2494:ex3:words:11:zh":"(polite tone)","grammar:2494:ex3:words:11:pos":"auxiliary verb","grammar:2494:ex3:points:0":"「verb dictionary form + こと」 nominalizes the action, making the whole phrase the object of 「計画する」.","grammar:2494:ex3:points:1":"The 「に」 in 「東京に」 marks the destination of the move.","grammar:2494:ex4:trans":"The preparations for the move are almost finished.","grammar:2494:ex4:structure":"verb dictionary form＋ための準備はほとんど終わりました","grammar:2494:ex4:explain":"「引っ越すための」 modifies 「準備」, showing the preparations made for moving. 「ほとんど終わりました」 means the preparations are mostly done, usually with a small part possibly left; 「終わる」 is an intransitive verb, and here it describes the preparations themselves being completed.","grammar:2494:ex4:words:0:zh":"to move house","grammar:2494:ex4:words:0:note":"ひっこす","grammar:2494:ex4:words:0:pos":"verb","grammar:2494:ex4:words:1:zh":"for the purpose of","grammar:2494:ex4:words:1:pos":"noun","grammar:2494:ex4:words:2:zh":"(modifies the noun that follows)","grammar:2494:ex4:words:2:pos":"particle","grammar:2494:ex4:words:3:zh":"prepare","grammar:2494:ex4:words:3:note":"じゅんび","grammar:2494:ex4:words:3:pos":"noun","grammar:2494:ex4:words:4:zh":"(topic)","grammar:2494:ex4:words:4:pos":"particle","grammar:2494:ex4:words:5:zh":"almost, nearly all","grammar:2494:ex4:words:5:pos":"adverb","grammar:2494:ex4:words:6:zh":"be finished, be over","grammar:2494:ex4:words:6:note":"おわり","grammar:2494:ex4:words:6:pos":"verb","grammar:2494:ex4:words:7:zh":"(polite tone)","grammar:2494:ex4:words:7:pos":"auxiliary verb","grammar:2494:ex4:words:8:zh":"(past, completed)","grammar:2494:ex4:words:8:pos":"auxiliary verb","grammar:2494:ex4:points:0":"「〜ための + noun」 expresses something that exists for a certain purpose.","grammar:2494:ex4:points:1":"With an affirmative sentence, 「ほとんど」 means almost all; with a negative sentence it usually means almost none.","grammar:2494:ex5:trans":"When I moved, a friend helped me out.","grammar:2494:ex5:structure":"verb dictionary form＋とき、〜が〜てくれました","grammar:2494:ex5:explain":"「引っ越すとき」 sets the time frame in which the friend helped. In 「友達が手伝ってくれました」 the friend is the one doing the action, and 「くれる」 expresses that I was the one receiving the help; the past tense for the whole event comes from the final 「ました」.","grammar:2494:ex5:words:0:zh":"to move house","grammar:2494:ex5:words:0:note":"ひっこす","grammar:2494:ex5:words:0:pos":"verb","grammar:2494:ex5:words:1:zh":"time","grammar:2494:ex5:words:1:pos":"noun","grammar:2494:ex5:words:2:zh":"friend","grammar:2494:ex5:words:2:note":"ともだち","grammar:2494:ex5:words:2:pos":"noun","grammar:2494:ex5:words:3:zh":"(nominative)","grammar:2494:ex5:words:3:pos":"particle","grammar:2494:ex5:words:4:zh":"help","grammar:2494:ex5:words:4:note":"てつだっ","grammar:2494:ex5:words:4:pos":"verb","grammar:2494:ex5:words:5:zh":"(connects the giving/receiving auxiliary verb)","grammar:2494:ex5:words:5:pos":"particle","grammar:2494:ex5:words:6:zh":"does (it) for me","grammar:2494:ex5:words:6:pos":"verb","grammar:2494:ex5:words:7:zh":"(polite tone)","grammar:2494:ex5:words:7:pos":"auxiliary verb","grammar:2494:ex5:words:8:zh":"(past, completed)","grammar:2494:ex5:words:8:pos":"auxiliary verb","grammar:2494:ex5:points:0":"「〜てくれる」 means someone does something for me or for my side.","grammar:2494:ex5:points:1":"「引っ越すとき」 can mean either when preparing to move or when actually moving, and it can be used even when the main event is in the past."},"2495":{"example:2495:exzh":"E-books are convenient.","example:2495:exzh2":"Electronic devices have changed daily life.","example:2495:exzh3":"I'll contact you by email.","example:2495:exzh4":"The electronic world is constantly evolving.","example:2495:exzh5":"He likes studying electronic circuits."},"2496":{"example:2496:exzh":"His efforts are valued.","example:2496:exzh2":"Work on the new project is starting.","example:2496:exzh3":"Passion for the work is important.","example:2496:exzh4":"The team's efforts produced results.","example:2496:exzh5":"She takes pride in her efforts."},"2497":{"example:2497:exzh":"His memory has faded away.","example:2497:exzh2":"It's sad when the truth fades away.","example:2497:exzh3":"That scenery has already faded away.","example:2497:exzh4":"I'm afraid her smile will fade away again.","example:2497:exzh5":"It's natural for memories to fade."},"2498":{"example:2498:exzh":"The view of the mountains is wonderful.","example:2498:exzh2":"He likes looking out the window.","example:2498:exzh3":"This view is special.","example:2498:exzh4":"She was moved by the view of the sea.","example:2498:exzh5":"I like the night view of the city."},"2499":{"example:2499:exzh":"Please drive carefully.","example:2499:exzh2":"He has a cautious personality.","example:2499:exzh3":"Being careful can help you avoid danger.","example:2499:exzh4":"I always make the children stay careful.","example:2499:exzh5":"This is work that requires caution."}};